return {["Life"]={["shenshi001"]={["acceptText"]=[[YEL#mz：多谢#ch#，我马上就动身前往京城给我娘买药。]],["chatId"]=[[chat002;chat003;chat004]],["chatId1"]=[[chat002;chat003;chat004]],["eventId"]=[[shenshi001]],["eventTalk"]=[[这冬虫夏草也太贵了吧。]],["id"]=[[shenshi001]],["lifeEvent"]=[[你见#mz平日虽和其他人相处不错，但独自一人时便会满面愁容，和#mz交流之后，才了解到#mz老家并不在此地，而家中母亲有病缠身，无人照料，多是邻里帮忙。#mz母亲的病全靠#mz在外做工支撑，所以#mz每天都过得十分忧愁。#mz和你聊了许久，将苦闷之事都向你倾诉，谈心之后，你们变得更为亲密了。]],["lifeEvent1"]=[[我娘身子已经好多了，这还得多亏#ch#费心。;娘叫我过些日子带些家里的土产来给#ch#尝尝鲜。;虽然我娘的病还是没有痊愈，但现在日子已经好过多了。]],["lifeText"]=[[HIY去京城协助仆人找到珍贵药材为他母亲补身子。]],["lifeText1"]=[[穷苦人家出身]],["lifeText2"]=[[穷苦人家出身，自小没了父亲，由母亲抚养长大]],["lifeText3"]=[[穷苦人家出身，自小没了父亲，由母亲抚养长大，是远近闻名的孝子。]],["talkText"]=[[不知道我家中老母过得可还算好。;要不是#ch#留我做工，我娘的药钱就没着落了。;我一个人出来做工，家里没人照料，全靠街坊们照顾我娘。]],["talktext1"]=[[我娘身子已经好多了，这还得多亏#ch#费心。;娘叫我过些日子带些家里的土产来给#ch#尝尝鲜。;虽然我娘的病还是没有痊愈，但现在日子已经好过多了。]],["taskText"]=[[#mz：#ch#，我娘最近老毛病犯了，好不容易治好，身子却大不如前。我想去京城给她找点冬虫夏草补补身子，想跟你告个假出去几天，成吗？]],["taskTitle"]=[[寻药救母]]},["shenshi002"]={["acceptText"]=[[YEL#mz：多谢#ch#，那我就下去收拾前往金陵城。]],["chatId"]=[[chat002;chat003;chat004]],["chatId1"]=[[chat002;chat003;chat004]],["eventId"]=[[shenshi002]],["eventTalk"]=[[我并不想招惹事端。]],["id"]=[[shenshi002]],["lifeEvent"]=[[#mz平日虽然待人和善，但似乎有意与谁都保持着一定的距离。在与#mz的交谈之中，#mz无意之中吐露出自己虽生在中原，但在西域长大，后西域小国攻打中原，#mz也被卷入其中。虽战争很快平息，但中原人都骂#mz是认贼作父的不义之人，#mz无法回到西域，在中原也只能艰难苟存。你得知#mz身世如此可怜，心中也是三分酸楚七分怜悯。]],["lifeEvent1"]=[[#ch#就是我的再造父母，往后我一定死心塌地地跟随#ch#。;#ch#的大恩大德，我没齿难忘。;从今往后我就是中原人，再不是什么西域人，我会为了中原而战，也会为了#ch#而战。]],["lifeText"]=[[HIY去金陵城看看仆人到底办什么事。]],["lifeText1"]=[[虽然长着一副中原人的脸，说话却偶尔带着西域的口音。]],["lifeText2"]=[[虽是汉人，却很小就随家人去了西域，并在那里长大。]],["lifeText3"]=[[虽是汉人，却很小就随家人去了西域，并在那里长大，传闻一度在西域某小国担任过实权武将、带过兵马。]],["talkText"]=[[#ch#最好还是不要和我扯上关系的好。;这里大家都对我很好，#ch#也待我如亲人，或许这就是家的感觉吧。;有时候回想起往事，就会彻夜难眠，前些日子王婶给了我一些安神香，效果不错，#ch#要是也睡不着，晚上我就替你点上。]],["talktext1"]=[[#ch#就是我的再造父母，往后我一定死心塌地地跟随你。;#ch#的大恩大德，我没齿难忘。;从今往后我就是中原人，再不是什么西域人，我会为了中原而战，也会为了#ch#而战。]],["taskText"]=[[#mz：#ch#，我有些急事要前往金陵数日，不知道可否歇工几日？]],["taskTitle"]=[[金陵追踪]]},["shenshi003"]={["acceptText"]=[[YEL#mz：谢谢#ch#这些日子对我的照顾，若是我不能回来…望#ch#多多珍重。]],["chatId"]=[[chat002;chat003;chat004]],["chatId1"]=[[chat002;chat003;chat004]],["eventId"]=[[shenshi003]],["eventTalk"]=[[虽然这事因我而起，但张大人的仇，我不得不报。]],["id"]=[[shenshi003]],["lifeEvent"]=[[你与#mz闲聊起来，你惊讶地发现#mz谈吐大度得体，对很多事都有独到的见解，像是见过大世面的人。仔细询问之下，#mz才告诉你缘由，原来#mz曾是一名官府的巡捕，曾为朝廷立下汗马功劳，但却嗜酒如命，一次醉酒耽误了大事，导致一位朝廷大员一家老小被仇家所杀，#mz也因此被革职。#mz发誓今生不再喝酒，你听罢，心中也是感概万千。]],["lifeEvent1"]=[[小人此生心愿已了，以后都愿意追随#ch#左右。;虽然说那赵千是罪有应得死不足惜，但毕竟我已经不再是官府的人，不应该插手此事。如果以后官府查证此事，我绝不会把#ch#交代出去的。;老李前些日子又找我来喝酒，被我揍了一顿。他恐怕再也不敢找我喝酒了，哈哈。]],["lifeText"]=[[HIY仆人去嵩山为张大人报仇，势单力薄，去助他一臂之力。]],["lifeText1"]=[[看起来与普通的乡野村夫无异，但眼中偶尔露出精干之色，应该是个有故事的人。]],["lifeText2"]=[[看起来与普通的乡野村夫无异，但眼中偶尔露出精干之色，行事有几分行伍之风，很可能曾是官府公门中人。]],["lifeText3"]=[[曾是官府的一名捕快，因为一些事情去职，曾经潦倒了一段很长的时间。]],["talkText"]=[[老李老是撺掇我和他一起去喝酒，这人真是老不正经，明知道我不能喝酒又馋得紧，还拿个酒葫芦天天在我眼前晃。;#ch#不用对我太好，像我这种喝酒误事的人，不值得别人期待。;我对过去做过的事真的很后悔，但是后悔是最没用的情绪，所以我只能严加克制自己，不能让类似的事情再次发生。]],["talktext1"]=[[小人此生心愿已了，以后都愿意追随#ch#左右。;虽然说那赵千是罪有应得死不足惜，但毕竟我已经不再是官府的人，不应该插手此事。如果以后官府查证此事，我绝不会把#ch#交代出去的。;老李前些日子又找我来喝酒，被我揍了一顿。他恐怕再也不敢找我喝酒了，哈哈。]],["taskText"]=[[#mz：这么多年的暗中调查，我终于找到那凶手就藏身嵩山。我想跟#ch#告个假，前去了解这桩旧事。]],["taskTitle"]=[[千里追凶]]},["shenshi004"]={["acceptText"]=[[YEL#mz：谢谢#ch#！我就不信青天大#ch#不替我做主了！]],["chatId"]=[[chat002;chat003;chat004]],["chatId1"]=[[chat002;chat003;chat004]],["eventId"]=[[shenshi004]],["eventTalk"]=[[这地一定得追回来。]],["id"]=[[shenshi004]],["lifeEvent"]=[[和#mz聊天的过程中，#mz告诉你自己曾是一个庄稼人，祖上留有几亩薄田，本来也是勤恳度日，没想被村中地主骗去田产，流落街头。#mz没有人可以求助，只得凭借几分气力，来此当了护院。]],["lifeEvent1"]=[[虽然我家里的地都追回来了，但我还是觉得做护院好，也能报答#ch#的恩情。;我已经把地给同村的王铁家里种了，这样一来他家的日子也能好过些。;要是这世上都是#ch#这样的好人就好了。;#ch#！我家里的地已经追回来了！哈哈。]],["lifeText"]=[[HIY去扬州衙门告状，为仆人讨回田产。]],["lifeText1"]=[[农户出身，看起来安分守己]],["lifeText2"]=[[农户出身，看起来是个本分人，通常来说这样的人容易吃亏、被人欺负。]],["lifeText3"]=[[农户出身。据说家里的田产被人巧取豪夺、成为失地流民，只能替人看家护院以维持生计。]],["talkText"]=[[昨天我出去买大饼，老板少找了我三文钱。我从小到大，都是被欺负的，村里的孩子也是，地主也是，连卖大饼的都瞧不起我。;我觉得现在的日子挺不错的，又轻松又有饭吃还有地方住，要不是#ch#肯收留我，我家里没了那一亩三分地，恐怕早就饿死在街头了。;#ch#有什么脏活粗活都可以吩咐，我以前是种地的，很多粗活都会做。]],["talktext1"]=[[虽然我家里的地都追回来了，但我还是觉得做护院好，也能报答#ch#的恩情。;要是这世上都是#ch#这样的好人就好了。;我已经把地给同村的王铁家里种了，这样一来他家的日子也能好过些。]],["taskText"]=[[#mz：#ch#！我想求你放我几天假，我要去扬州衙门告一状，把家里的地都讨回来。]],["taskTitle"]=[[讨回田产]]},["shenshi005"]={["acceptText"]=[[YEL#mz：多谢#ch#！我这就去安排，一切就麻烦#ch#你了。]],["chatId"]=[[chat002;chat003;chat004]],["chatId1"]=[[chat002;chat003;chat004]],["eventId"]=[[shenshi005]],["eventTalk"]=[[那真是我师父吗？]],["id"]=[[shenshi005]],["lifeEvent"]=[[你和#mz聊起天来，无意中聊到关于打猎的事，#mz顿时显得十分感兴趣，向你说了许多打猎的经验。你心中奇怪，便询问到#mz的身世，原来#mz曾经是名孤儿，被抛弃在深山之中，被#mz的师父捡了回来，并将其一手养大。后来#mz师父说是去游山玩水，也再没了下落，#mz才出来寻找师父。]],["lifeEvent1"]=[[师父他老人家既然不想被人打扰地过日子，我也只能了他心愿，偶尔去看看他。;在这世上除了师父是我最重要的人之外，就只有#ch#你是我的亲人了。;师父最近身子不错，还能上山采些补药给我，他一个老人尚且不吃这些，倒显得我还不如他了。]],["lifeText"]=[[HIY去太行谷帮助仆人寻找师父。]],["lifeText1"]=[[无父无母，孑然一身，不知道被何人抚养长大，身手比一般人要矫健很多。]],["lifeText2"]=[[孤儿出身，为人和善，一身打猎的本领不知学自何人。]],["lifeText3"]=[[孤儿出身，被一位世外高人抚养长大。]],["talkText"]=[[不知道我师父到底去了哪，找了这么久，也还是没找到。;#ch#若是想寻点野味来吃吃，我可以去替你寻来，不是我自夸，这天上飞的水里游的地上跑的，没有我打不到的。;我这一身本领都是和我师父学的，他老人家可比我要厉害多了。]],["talktext1"]=[[师父他老人家既然不想被人打扰地过日子，我也只能了他心愿，偶尔去看看他。;在这世上除了师父是我最重要的人之外，就只有#ch#你是我的亲人了。;师父最近身子不错，还能上山采些补药给我，他一个老人尚且不吃这些，倒显得我一个精壮汉子还不如他了。]],["taskText"]=[[#mz：#ch#，我听人说起看到太行谷深山之中有一个老者出没，我在想那会不会是我离家多年的师父，想去一探究竟。太行谷很大，找一个人并不容易，不知道能不能麻烦#ch#你和我一起去。]],["taskTitle"]=[[寻找师父]]},["shenshi006"]={["acceptText"]=[[YEL#mz：多谢#ch#！我这就去。]],["chatId"]=[[chat007;chat010;chat011;chat012;chat013]],["chatId1"]=[[chat007;chat010;chat011;chat012;chat013]],["eventId"]=[[shenshi006]],["eventTalk"]=[[我定要考取功名，光宗耀祖。]],["id"]=[[shenshi006]],["lifeEvent"]=[[一日闲聊之中你了解到#mz是家中独子，小时候被家中父母寄予厚望、希望他能考取功名光宗耀祖，就送他去读了几年书。后来家道中落，没钱读书，只得去大户人家当书童为生。]],["lifeEvent1"]=[[#ch#的大恩大德，我这辈子也不会忘，如果我将来能够高中，一定会报答#ch#的。;上次乡试我感觉发挥得不错，想来中一个秀才是没问题的。;虽说#ch#并没有打算要我还钱，但滴水之恩当涌泉相报，这钱我一定会慢慢还给#ch#的。]],["lifeText"]=[[HIY仆人去牛家村参加乡试，去替他助威。]],["lifeText1"]=[[识文断字，举止有礼，看起来也是读过几年书的。]],["lifeText2"]=[[似乎出自家境殷实的人家，不知为何不去就学，而是来做一名书童。]],["lifeText3"]=[[本是一名富户人家的独子，有比较强的向学之心，只是家道中落，无以为继。]],["talkText"]=[[我跟着#ch#多读几年书，将来也是有希望考上秀才的吧？;虽然我家里没钱供我念书，但能陪在#ch#身边读书识字，我也就心满意足了。;#ch##ch#，我有一个字不会念，您能教教我吗？]],["talktext1"]=[[#ch#的大恩大德，我这辈子也不会忘，如果我将来能够高中，一定会报答#ch#的。;上次乡试我感觉发挥得不错，想来中一个秀才是没问题的。;虽说#ch#可能并没有打算要我还钱，但滴水之恩当涌泉相报，这钱我一定会慢慢还给#ch#的。]],["taskText"]=[[#mz：#ch#，我想和您商量点事。我去牛家村参加乡试，可以吗？]],["taskTitle"]=[[乡试助威]]},["shenshi007"]={["acceptText"]=[[YEL#mz：她家现住在金陵城中，谢谢#ch#。]],["chatId"]=[[chat007;chat010;chat011;chat012;chat013]],["chatId1"]=[[chat007;chat010;chat011;chat012;chat013]],["eventId"]=[[shenshi007]],["eventTalk"]=[[她会不会拒绝我呢。]],["id"]=[[shenshi007]],["lifeEvent"]=[[你见#mz有时候会一幅有心事的样子，便留了个心眼，找了个机会向他询问原因。#mz一开始支支吾吾不肯说，后来告诉你是因为他喜欢上了一个女子，却不知道那女子对他心思如何，又不敢明示。他向你倾吐了很多心事，诸如如何遇见她，她的性格又是如何等，你静静地聆听着，末了也为他鼓劲，经此一事，#mz对你更为信任了。]],["lifeEvent1"]=[[她对我很好，我打算过些日子就向她家里正式提亲了。;这桩姻缘也是#ch#促成的，若不是#ch#你，我也不能迈出这最后一步。;若是我和她成亲了，还请#ch#一定来替我主持婚事，并喝上一杯喜酒。]],["lifeText"]=[[HIY去金陵城帮助仆人顺利向心上人表明心意。]],["lifeText1"]=[[勃勃有生气，正是知慕少艾的年纪]],["lifeText2"]=[[勃勃有生气，正是知慕少艾的年纪]],["lifeText3"]=[[勃勃有生气，正是知慕少艾的年纪]],["talkText"]=[[我心中已有心上之人，却不知道她心属何处。;诗经之中关于描写男女之情的篇章着实不少，古人尚且如此开放，为什么我却不能鼓起勇气。;如果#ch#有了心上之人，那你会怎么做呢。]],["talktext1"]=[[她对我很好，等我长大了，一定娶她为妻。;这事也是#ch#促成的，若不是#ch#你，我也不能迈出这最后一步。;若是我将来和她成亲了，还请#ch#一定来替我主持婚事，并喝上一杯喜酒。]],["taskText"]=[[#mz：#ch#，您还记得我之前和你说的那位姑娘吗？我，我想去向她表达心意，但一个人又不敢…#ch#您能陪我去吗？]],["taskTitle"]=[[千里姻缘]]},["shenshi008"]={["acceptText"]=[[YEL#mz：多谢#ch#，那我就下去收拾前往襄阳城。]],["chatId"]=[[chat007;chat010;chat011;chat012;chat013]],["chatId1"]=[[chat007;chat010;chat011;chat012;chat013]],["eventId"]=[[shenshi008]],["eventTalk"]=[[不知道又有谁招惹了仇家。]],["id"]=[[shenshi008]],["lifeEvent"]=[[你和#mz闲聊起来，无意之中聊到江湖上的事情，#mz对江湖之事似乎十分了解，在你的询问之下，#mz隐晦地告诉你他和与永夜楼有些渊源。你对永夜楼这个拿钱杀人的刺客组织有些兴趣，但他似乎不愿意告诉你更多过去之事。]],["lifeEvent1"]=[[虽然我是永夜中人，但也只是个不入流的刺客，大多数时间还是干别的活来过日子。;#ch#可别因为我是个刺客就不要我了啊！我其实很喜欢做书童这种宁静的日子。;其实永夜楼也没有大家想的那么神秘，不过就是一群替人办事的人。]],["lifeText"]=[[HIY去襄阳看看仆人处理什么私事。]],["lifeText1"]=[[虽然年纪不大，但似乎有着与年龄不符的成熟和沧桑。]],["lifeText2"]=[[虽然年纪不大，但似乎有着与年龄不符的成熟和沧桑，似乎曾是个江湖中人。]],["lifeText3"]=[[年纪轻轻便退隐江湖的刺客，是一个将自己和过去割裂开的人。]],["talkText"]=[[#ch#知道江湖上有一个专门替人用钱杀人的组织吗？;#ch#平时闯荡江湖定要多加小心谨慎，保不准有人就会在暗中下手害你性命。;人在江湖上讨生活，很多事情都是身不由己的，有时候连自己性命都无法掌握。]],["talktext1"]=[[虽然我是永夜中人，但因为年纪小，也不过也是个不入流的二流刺客，大多数时间还是干别的活来过日子。;#ch#可别因为我是个刺客就不要我了啊！我其实很喜欢做书童这种宁静的日子。;其实永夜楼也没有大家想的那么神秘，不过就是一群替人办事的人。]],["taskText"]=[[#mz：#ch#，我有些私事要处理，要去一趟襄阳城。过几日便会回来。]],["taskTitle"]=[[永夜之城]]},["shenshi009"]={["acceptText"]=[[YEL#mz：多谢#ch#。]],["chatId"]=[[chat007;chat010;chat011;chat012;chat013]],["chatId1"]=[[chat007;chat010;chat011;chat012;chat013]],["eventId"]=[[shenshi009]],["eventTalk"]=[[我爹不会有什么事吧。]],["id"]=[[shenshi009]],["lifeEvent"]=[[你和#mz闲聊起来，无意之中聊到#mz的身世，#mz告诉你他家原本是武学世家，他又是家中独子，本被寄予厚望，但他打小便喜欢吟诗作对，对舞刀弄枪没有兴趣，家里逼得急了，他一怒之下才从家里逃了出来。看他如今的状态，虽然只做个小小书童，但毕竟做着自己喜欢的事，每天倒也过得开心。]],["lifeEvent1"]=[[前些日子我和我爹聊过了，我爹虽然还是希望我能继承祖业，但也不会再过问我的生活。;虽然我爹不再逼我了，但真到这份上，我反倒觉得有些对不住他。;若不是#ch#帮忙，我和我爹恐怕这辈子都没法重归于好了。]],["lifeText"]=[[HIY去华山村探望仆人生病的父亲。]],["lifeText1"]=[[喜读诗书，性子文静，是一个伴读的好人选。]],["lifeText2"]=[[喜读诗书，性子文静，是一个伴读的好人选，不过似乎也有些武学底子。]],["lifeText3"]=[[出身武学世家，家学渊源，但喜诗书，对继承家业很是抗拒。]],["talkText"]=[[我爹对我管教很严格，他希望我日后可以从军保家卫国，我却没有那么大的理想。;#ch#，要是不认识的人问起我的事，您可千万别告诉他。;如果家里人逼迫#ch#做不想做的事，#ch#你会如何对待呢。]],["talktext1"]=[[前些日子我和我爹聊过了，我爹虽然还是希望我能继承祖业，但也不会再过问我向往的生活。;虽然我爹不再逼我了，但真到这份上，我反倒觉得有些对不住他。;若不是#ch#帮忙，我和我爹恐怕这辈子都没法重归于好了。]],["taskText"]=[[#mz：#ch#，我想告个假回华山村一趟，家里传信来说我爹得了病，生为人子，我必须去照顾他。]],["taskTitle"]=[[华山探病]]},["shenshi010"]={["acceptText"]=[[YEL#mz：多谢#ch#，此次前往牛家村乡试，我定会出人头地的。]],["chatId"]=[[chat007;chat010;chat011;chat012;chat013]],["chatId1"]=[[chat007;chat010;chat011;chat012;chat013]],["eventId"]=[[shenshi010]],["eventTalk"]=[[我一定要考上秀才，这是我唯一的出路。]],["id"]=[[shenshi010]],["lifeEvent"]=[[你见#mz平时没有陪读的时候也自己默默看书，知道他是一个十分努力的人，但似乎总是抓不住诀窍。和你聊天之中，你得知#mz三岁能文，五岁能诗，本是能成材之人，可他家人并没有因此对他多加栽培，而是四处炫耀，导致他逐渐被埋没。如今他家中逼得更紧，要他努力向学，但朽木已成，已经是回天乏术，你听到此处，心中只能叹息。]],["lifeEvent1"]=[[我现在已经认清了自己，再也不用活的那么累了。;多谢#ch#对我的指点，能陪在#ch#身旁，也是我的荣幸。;幼时那些不寻常的日子我都忘得差不多了，还是如今的平淡日子比较适合我。]],["lifeText"]=[[HIY仆人去牛家村参加乡试，去替他助威。]],["lifeText1"]=[[虽然看起来有些驽钝，但也是一个一心向学之人。]],["lifeText2"]=[[虽然看起来有些驽钝，但也是一个一心向学之人。]],["lifeText3"]=[[曾经天资聪颖，可惜没有得到很好的栽培，如今对自己的人生已经不再抱有幻想。]],["talkText"]=[[#ch#，我有一些诗词不太懂其中道理，如果#ch#有空，可以给我讲解一二吗？;我真笨，为什么这么简单的书都读不懂呢。;我将来一定能出人头地！]],["talktext1"]=[[我现在已经认清了自己，再也不用活的那么累了。;多谢#ch#对我的指点，能陪在#ch#身旁，也是我的荣幸。;幼时那些不寻常的日子我都忘得差不多了，还是如今的平淡日子比较适合我。]],["taskText"]=[[#mz：#ch#，我读了许久的书，想要去牛家村参加乡试。还请#ch#准许我外出。]],["taskTitle"]=[[乡试助威]]},["shenshi011"]={["acceptText"]=[[YEL#mz：谢谢#ch#！那我收拾一下就去找家客栈落脚。]],["chatId"]=[[chat001;chat002;chat006;chat009;chat010]],["chatId1"]=[[chat001;chat002;chat006;chat009;chat010]],["eventId"]=[[shenshi011]],["eventTalk"]=[[乞巧节上人才济济，我也不知道自己成不成。]],["id"]=[[shenshi011]],["lifeEvent"]=[[你在#mz刺绣的时候和她聊起天来，她告诉你在她的家乡女子均要在合适的年纪去京城参加乞巧节，只有夺得上好成绩者才能在人前扬眉吐气。好的绣娘提亲者踏破门槛，而手艺不精者恐怕终身难以嫁人。虽然你觉得女子的终身大事不应该只由刺绣来定夺，但这毕竟是她们的风俗，你也不好说什么。]],["lifeEvent1"]=[[虽然我没能夺得魁首，但好歹也是个第二，这在科举上也算个榜眼了吧？嘿嘿。;这次乞巧节若不是#ch#帮忙，我恐怕连刺绣都完不成。#ch#真是除了我爹娘对我最好的人了。;自从上次乞巧节之后，来找我爹提亲的人一下子多了起来，可我现在并不想嫁人，我只想…陪在#ch#您的身边。]],["lifeText"]=[[HIY和仆人一起去京城参加乞巧节。]],["lifeText1"]=[[来自异乡的绣女，有不错的刺绣女红手艺。]],["lifeText2"]=[[来自异乡的绣女，有不错的刺绣女红手艺。]],["lifeText3"]=[[来自异乡的绣女，对自己刺绣女红手艺要求十分苛刻，似乎当成一种人生必须完成的成就来看待。]],["talkText"]=[[#ch#，您听说过乞巧节吗？今年我也打算去京城参加乞巧节。;我没有想好今年乞巧节绣什么好，#ch#可有什么好的想法？;您觉得我的手艺，能在乞巧节上讨得彩头吗……]],["talktext1"]=[[虽然我没能夺得魁首，但好歹也是个第二，这在科举上也算个榜眼了吧？嘿嘿。;这次乞巧节若不是#ch#帮忙，我恐怕连刺绣都完不成。#ch#真是除了我爹娘对我最好的人了。;自从上次乞巧节之后，来找我爹提亲的人一下子多了起来，可我现在并不想嫁人，我只想…陪在#ch#您的身边。]],["taskText"]=[[#mz：不久之后京城就要举办乞巧节了，虽然我还没想好绣什么，但也差不多该去了。我想向#ch#告个假，您看行吗？]],["taskTitle"]=[[乞巧佳节]]},["shenshi012"]={["acceptText"]=[[YEL#mz：金陵城中有一家比较大的裁缝店，可能对此事有所了解。]],["chatId"]=[[chat001;chat002;chat006;chat009;chat010]],["chatId1"]=[[chat001;chat002;chat006;chat009;chat010]],["eventId"]=[[shenshi012]],["eventTalk"]=[[希望能找到会双面刺绣之人。]],["id"]=[[shenshi012]],["lifeEvent"]=[[你听#mz平日里时常提起双面刺绣的事情，一时心中好奇，便找个机会向她询问了此事。她告诉你她毕生所愿便是能学会双面刺绣的绝学，但能双面刺绣的人很少，她只听说过江南有一位绣娘会，虽有心想拜之为师，但又不知道从何寻找，所以心中烦闷。]],["lifeEvent1"]=[[双面刺绣果然很难，我会努力学习的。;师父她对我很好，传授了我不少关于刺绣的技巧，下次也试着给#ch#绣点东西吧。;最近感觉能稍微掌握一点诀窍了。]],["lifeText"]=[[HIY去金陵城帮助仆人找到会双面刺绣之人。]],["lifeText1"]=[[对刺绣手工很有天赋的女子]],["lifeText2"]=[[对刺绣手工很有天赋的女子]],["lifeText3"]=[[对刺绣手工很有天赋的女子，追寻着古老的双面刺绣的技艺。]],["talkText"]=[[#ch#您听说过双面刺绣吗？由于刺绣背面要藏线头，双面刺绣就意味着背面的线头都要藏在刺绣之中，这可不是人人都能做的事情。;听说江南一带有一位会双面刺绣的绣娘。;我何时能成为那般优秀的绣娘呢。]],["talktext1"]=[[双面刺绣果然很难，我会努力学习的。;师父她对我很好，传授了我不少关于刺绣的技巧，下次也试着给#ch#绣点东西吧。;最近感觉能稍微掌握一点诀窍了。]],["taskText"]=[[#mz：#ch#，我想去寻找那位会双面刺绣的绣娘学艺，但不知她姓甚名谁，家住何处。#ch#能否助我一同前去寻找？]],["taskTitle"]=[[双面刺绣]]},["shenshi013"]={["acceptText"]=[[YEL#mz：真的吗？谢谢#ch#！钱员外家住华山村，求#ch#一定要替我做主啊！]],["chatId"]=[[chat001;chat002;chat006;chat009;chat010]],["chatId1"]=[[chat001;chat002;chat006;chat009;chat010]],["eventId"]=[[shenshi013]],["eventTalk"]=[[要我嫁给他，我情愿一死了之，可那样我的母亲又该怎么办呢。]],["id"]=[[shenshi013]],["lifeEvent"]=[[#mz近时常愁眉不展，似心中有万千苦闷。你和她聊天解闷时，她向你吐露了心事，原来她父亲早亡，母亲一人把她拉扯大，家中无一男丁，讨生活自然不容易，家中也因此欠下不少外债。如今那放债的钱员外见她出落得漂亮，便打主意让她嫁给家中小儿子为妾，可他那儿子是四邻八乡出了名的恶少，她若是嫁过去，只怕活不过半年。]],["lifeEvent1"]=[[多谢#ch#出手相助，那钱员外如今再也不敢对我家怎么样了。#ch#的恩情我这辈子都不会忘。;若是我能找到如意郎君，到时候一定会宴请#ch#。;这些年因为债务的关系，我娘辛勤劳作，身子也不是很好，现在没了债务，她身子已经比以前好多了。]],["lifeText"]=[[HIY去华山村替仆人拒绝婚事。]],["lifeText1"]=[[吃苦耐劳，手脚勤快，但有时候看起来心事重重。]],["lifeText2"]=[[吃苦耐劳，手脚勤快，但有时候看起来心事重重，似乎是家里的经济状况不乐观。]],["lifeText3"]=[[父亲早亡，由母亲带大，家中负债累累，勉力支撑，在家事和个人婚姻的双重巨压下艰难地寻找出路。]],["talkText"]=[[为什么女子都不能自己追求幸福呢？;若是能有来生，我一定不做女儿身。;这里的人都对我很好，有时候会使我忘掉家中的烦恼。]],["talktext1"]=[[多谢#ch#出手相助，那钱员外如今再也不敢对我家怎么样了。#ch#的恩情我这辈子都不会忘。;若是我能找到如意郎君，到时候一定会宴请#ch#。;这些年因为债务的关系，我娘辛勤劳作，身子也不是很好，现在没了债务，她身子已经比以前好多了。]],["taskText"]=[[#mz：#ch#，求您救救我！我家里欠下的债，钱老爷要我嫁给他小儿子来抵。他那儿子性格顽劣不堪，我若是嫁过去，只怕没有好下场。#ch#您救救我啊！]],["taskTitle"]=[[员外逼婚]]},["shenshi014"]={["acceptText"]=[[YEL#mz：那我们便一同走吧。]],["chatId"]=[[chat001;chat002;chat006;chat009;chat010]],["chatId1"]=[[chat001;chat002;chat006;chat009;chat010]],["eventId"]=[[shenshi014]],["eventTalk"]=[[家里的针线用完了。]],["id"]=[[shenshi014]],["lifeEvent"]=[[#mz平日里时常提起幼妹的事，你找她聊天的时候偶然之间提及此事，#mz告诉你她家中原本还有个小她两岁的妹妹，几年前家乡闹饥荒时，她爹娘带着她和妹妹离开家乡，颠沛流离之间，妹妹在路途中走失。#mz与家人多年寻找均未能找到她，现在也不知是死是生。#mz说着，眼中逐渐湿润，不多时便垂下泪来。]],["lifeEvent1"]=[[我妹妹如今已经回到家中生活，这些年真是苦了她了。;过些日子我打算也将刺绣的功夫教给我妹妹，让她也找一门营生。;以前每逢过节，爹娘都是闷闷不乐的，现在好多了。]],["lifeText"]=[[HIY去金陵城和仆人一起置办针线。]],["lifeText1"]=[[出身于良善之家，秀外慧中，举止得体。]],["lifeText2"]=[[出身于良善之家，秀外慧中，举止得体。不过有时会陷入忧伤的境地，一个人躲起来暗自垂泪。]],["lifeText3"]=[[出身于良善之家，秀外慧中，举止得体。不过有时会陷入忧伤的境地，一个人躲起来暗自垂泪，应该是跟家人有关。]],["talkText"]=[[#ch#可知道与亲人不得相见的思念之苦？;年少时我与家人漂泊无依，爹娘都过惯了苦日子，如今生活趋于稳定，每次回想起以前的日子，爹娘都会念及幼妹。;每逢佳节倍思亲，我何时才能一家团圆呢。]],["talktext1"]=[[我妹妹如今已经回到家中生活，这些年真是苦了她了。;过些日子我打算也将刺绣的功夫教给我妹妹，让她也找一门营生。;以前每逢过节，爹娘都是闷闷不乐的，现在好多了。]],["taskText"]=[[#mz：#ch#，我正打算去金陵城置办些针线一类的东西，#ch#要是清闲，可以一同去看看风景。]],["taskTitle"]=[[置办针线]]},["shenshi015"]={["acceptText"]=[[YEL#mz：多谢#ch#！我也会一同前去，劝说我哥哥。]],["chatId"]=[[chat001;chat002;chat006;chat009;chat010]],["chatId1"]=[[chat001;chat002;chat006;chat009;chat010]],["eventId"]=[[shenshi015]],["eventTalk"]=[[哥哥深陷贼窟，爹娘可要担心死了。]],["id"]=[[shenshi015]],["lifeEvent"]=[[你和#mz聊到她的家世，她告诉你她家家中父母健在，又小有积蓄，本该是和睦的一家，只是她兄长听信什么柴帮的话，加入柴帮，整日寻思着劫富济贫，其实不过是一群混混不学无术。#mz的哥哥原本十分老实，如今却再也不听家里人的话，还会骗去家中钱财上交帮主，她娘也气得病倒在床。]],["lifeEvent1"]=[[哥哥他在家人的劝说之下如今已经痛改前非，这都要多亏#ch#捣毁柴帮。;既然有一个柴帮祸害人，那肯定还有别的什么帮也存在于世上，还有更多的人在因之受苦。;我哥哥已经开始操持家务，想来我娘的病也能减轻一些。]],["lifeText"]=[[HIY去太行谷替仆人捣毁柴帮。]],["lifeText1"]=[[出身于小康之家，父母都是本分之人。]],["lifeText2"]=[[出身于小康之家，父母都是本分之人，有一个长兄，听说似乎有点让人不省心。]],["lifeText3"]=[[出身于小康之家，父母都是本分之人，有一个长兄，听说似乎有点让人不省心。]],["talkText"]=[[家中兄长如此不争气，可真叫人发愁。;#ch#您平时闯荡江湖，见多识广，可有听说过什么叫“柴帮”的江湖势力？;要不是我哥哥不听劝告一意孤行，我娘如何会气得卧病在床。]],["talktext1"]=[[哥哥他在家人的劝说之下如今已经痛改前非，这都要多亏#ch#捣毁柴帮。;既然有一个柴帮祸害人，那肯定还有别的什么帮也存在于世上，还有更多的人在因之受苦。;我哥哥已经开始操持家务，想来我娘的病也能减轻一些。]],["taskText"]=[[#mz：我有一事相求#ch#。我调查到了那柴帮的总据点，正在太行谷内。那里的人就是一群山贼，我哥哥如今已经落入贼窝。我想求#ch#去捣毁柴帮，救出我哥哥。]],["taskTitle"]=[[捣毁柴帮]]},["shenshi016"]={["acceptText"]=[[YEL#mz：有劳#ch#了。]],["chatId"]=[[chat001;chat002;chat005;chat014]],["chatId1"]=[[chat001;chat002;chat005;chat014]],["eventId"]=[[shenshi016]],["eventTalk"]=[[我一定要完成老太婆的心愿。]],["id"]=[[shenshi016]],["lifeEvent"]=[[闲暇之际，你和#mz聊起了从前的事，#mz回忆起他的妻子，开始向你诉说往事。#mz与他妻子是青梅竹马，结为夫妻之后恩爱异常。二人都喜欢侍弄花草，也种出来很多奇花异草，后#mz的妻子病重，希望能葬于白色桃花之下，只是#mz从未见过白色桃花，不知何处去寻。]],["lifeEvent1"]=[[要是我能在#ch#这终老，也想请#ch#把我和她葬在一起。;我知道她其实并不是真的喜欢白色桃花，而是在怀念小时候我们一起在桃花林中嬉戏玩耍的日子。;我一定会悉心照料这些桃树。]],["lifeText"]=[[HIY去落英谷助仆人找寻白色桃花。]],["lifeText1"]=[[普通农户，侍弄庄稼是把好手。]],["lifeText2"]=[[普通农户，侍弄庄稼是把好手。]],["lifeText3"]=[[普通农户，侍弄庄稼是把好手。妻子故去多年，是个老鳏夫，对亡妻很是怀念。]],["talkText"]=[[我那老太婆走之前梦到漫山遍野的白色桃花，一直念念不忘。;老头我种了这么多年花草，见过粉的，红的，粉白的桃花，从来没见过纯白色的桃花。;老太婆的心愿恐怕一辈子没法完成了。]],["talktext1"]=[[要是我能在#ch#这终老，也想请#ch#把我和她葬在一起。;我知道她其实并不是真的喜欢白色桃花，而是在怀念小时候我们一起在桃花林中嬉戏玩耍的日子。;我一定会悉心照料这些桃树。]],["taskText"]=[[#mz：今天是老太婆生辰，也是她离我而去的日子。我希望能完成她的心愿，找到白色的桃花。都说落英谷是一个奇花异草盛开的地方，我想去碰碰运气。不知道#ch#是否愿意和我同去？]],["taskTitle"]=[[白色桃花]]},["shenshi017"]={["acceptText"]=[[YEL#mz：多谢#ch#。只是听说这万灵谷的人大多性子古怪，不知道能不能轻易地求到药。]],["chatId"]=[[chat001;chat002;chat005;chat014]],["chatId1"]=[[chat001;chat002;chat005;chat014]],["eventId"]=[[shenshi017]],["eventTalk"]=[[怎样才能配成药方呢？]],["id"]=[[shenshi017]],["lifeEvent"]=[[你和#mz闲来无事，聊起天来，#mz不仅对种植药材十分有心得，对医理也懂得不少。如今#mz在想新的药方，并打算收集药材试试药方的效果，因此最近都埋头在药田之间忙碌。]],["lifeEvent1"]=[[这方子虽然失败了，但我已经吸取教训，下次定会做得更好。;虽然这次的药方没能成功，但还是要谢谢#ch#你不辞辛苦地帮我找来药材。;若是我能自己栽种那些珍贵药材，找药的时候就不会那么麻烦了。]],["lifeText"]=[[HIY去万灵谷助仆人找几味毒药。]],["lifeText1"]=[[普通农户出身，似乎能识文断字，非一般大老粗。]],["lifeText2"]=[[普通农户出身，似乎能识文断字，对药理、药材也有一定了解。]],["lifeText3"]=[[普通农户出身，似乎能识文断字，对药理、药材也有一定了解。]],["talkText"]=[[种草药种久了，对药理自然有些了解，这和久病成良医是同样的道理。;我年轻的时候跟随大夫做了几年药童，大夫教授了我不少药理。;药能救人，但也能杀人，用处不同，用法也不一样。]],["talktext1"]=[[这方子虽然失败了，但我已经吸取教训，下次定会做得更好。;虽然这次的药方没能成功，但还是要谢谢#ch#你救了我的性命。;若是我能自己栽种那些珍贵药材，找药的时候就不会那么麻烦了。]],["taskText"]=[[#mz：我想了一个新的方子，此药方讲究以毒攻毒，可有几味毒药实在难找。我想去万灵谷求这几味毒药，所以想给#ch#告几天假。]],["taskTitle"]=[[治病毒药]]},["shenshi018"]={["acceptText"]=[[YEL#mz：那我就先行一步。]],["chatId"]=[[chat001;chat002;chat005;chat014]],["chatId1"]=[[chat001;chat002;chat005;chat014]],["eventId"]=[[shenshi018]],["eventTalk"]=[[毒物泡酒，真是新鲜啊。]],["id"]=[[shenshi018]],["lifeEvent"]=[[你和#mz闲聊了一会，从闲聊之中得知#mz十分好酒，从前云游四海，将天下好酒都喝了个遍，后来就开始自己酿酒，并在酒中加入药材，酿出的药酒既甘醇又对身体大有裨益。#mz见你似乎有兴趣，还邀请你下次一起来喝酒，#mz与你似乎更为亲密了。]],["lifeEvent1"]=[[能喝到这种好酒，我这辈子走这一遭值了。;是#ch#啊。啥时候来和我一起喝一杯吧。;多谢#ch#不辞辛苦替我找来酒，我也没啥好报答你的，今后#ch#有啥事尽管吩咐我。]],["lifeText"]=[[HIY去万灵谷和仆人一起找寻毒物泡的酒。]],["lifeText1"]=[[饱经沧桑，见多识广，是一个很有故事的人。]],["lifeText2"]=[[饱经沧桑，见多识广，是一个很有故事的人。]],["lifeText3"]=[[饱经沧桑，见多识广，是一个很有故事的人，最大的喜好是喝酒，不过从来没有贪杯误事罢了。]],["talkText"]=[[老头没啥喜好，就是好嘴上这一口。;老头我活了几十年，啥样的酒都见过。;就是那最寻常不过的烧刀子，长久的喝也有不寻常的味道，喝酒和生活是一个道理，平凡才是最真。]],["talktext1"]=[[能喝到这种好酒，老头这辈子走这一遭也值得了。;是#ch#啊。啥时候来和我一起喝一杯吧。;多谢#ch#不辞辛苦替老头找来酒，老头也没啥好报答你的，但今后#ch#有啥事尽管吩咐我。]],["taskText"]=[[#mz：老头最近听人说万灵那有人用毒物泡酒，老头我从没喝过毒物泡的酒，如今酒虫难耐，定要去试一试。]],["taskTitle"]=[[毒虫入酒]]},["shenshi019"]={["acceptText"]=[[YEL#mz：多谢#ch#！]],["chatId"]=[[chat001;chat002;chat005;chat014]],["chatId1"]=[[chat001;chat002;chat005;chat014]],["eventId"]=[[shenshi019]],["eventTalk"]=[[不知道这次玉器交易能不能遇到我家的传家宝。]],["id"]=[[shenshi019]],["lifeEvent"]=[[你和#mz聊起了过去，#mz告诉你自己家中原本富裕，后家中连遭变故，不仅家财散尽，祖上世世代代传下来的传家宝也遗失不见。#mz父亲有感愧对列祖列宗，积忧成疾，一直卧床不起，不久就去世了。#mz如今也已过了壮年，虽无法重振家业，但还是希望能找回传家宝，完成父亲的遗愿。]],["lifeEvent1"]=[[虽然我已经不再年少，但我定会教我子孙重振家业。;传家宝能找回来，也算是祖上积德了。;我爹的遗愿终于能完成了。]],["lifeText"]=[[HIY去京城参加玉器交易会，助仆人寻回传家宝。]],["lifeText1"]=[[虽然是个庄稼汉，但举止有度，不卑不亢，显示出极好的修养。]],["lifeText2"]=[[虽然是个庄稼汉，但举止有度，不卑不亢，显示出极好的修养，似乎家中也曾显贵过，因为家道中落，才潦倒下尘。]],["lifeText3"]=[[出身于巨富之家，对找回丢失的传家宝有种特殊的执念。]],["talkText"]=[[现在的日子过于美好，以至于有时候一觉醒来，会让人感觉方才不过在梦中。;当年我家虽然不算是富甲一方，但也是我家乡数一数二的富贵之家。;我爹当年留下来的东西一定不能落入外人之手。]],["talktext1"]=[[虽然我已经老去，但我定会教我子孙重振家业。;传家宝能找回来，也算是祖上积德了。;我爹的遗愿终于能完成了。]],["taskText"]=[[#mz：我听说不就之后京城有一场玉器交易会，我家遗失的宝物是一件圆雕黄玉虎，也是玉器，有可能也会出现在那。我想去京城看看。]],["taskTitle"]=[[玉器交易]]},["shenshi020"]={["acceptText"]=[[YEL#mz：那好，多谢#ch#。]],["chatId"]=[[chat001;chat002;chat005;chat014]],["chatId1"]=[[chat001;chat002;chat005;chat014]],["eventId"]=[[shenshi020]],["eventTalk"]=[[那小子真的能改良翻车吗？]],["id"]=[[shenshi020]],["lifeEvent"]=[[你和#mz聊到平日里耕种药圃的事，#mz谈到随着田圃越来越多，单靠#mz一人挑水灌溉也不是长久之计。#mz之前尝试着用翻车来灌溉，但效果并不理想，如今正是愁眉不展。你将#mz的烦恼记在心中，寻思着也想想办法。]],["lifeEvent1"]=[[这种改良后的翻车当真是好用，老头子也轻松多啦。;现在的年轻人这么能干，真是长江后浪推前浪啊。;#ch#要不要给这种改良的翻车起个什么名字？]],["lifeText"]=[[HIY去逍遥林替仆人找能改良翻车的匠人。]],["lifeText1"]=[[普通农户，和庄稼打了大半辈子的交道。]],["lifeText2"]=[[普通农户，和庄稼打了大半辈子的交道。]],["lifeText3"]=[[普通农户，和庄稼打了大半辈子的交道，对操持农活有种天然的热爱。]],["talkText"]=[[#ch#的田圃越来越多，这浇灌起来也越来越不容易了。;有没有什么快速浇灌田地的方法？;汉时有人用翻车浇灌农田，不知道这小亩地能不能行。]],["talktext1"]=[[这种改良后的翻车当真是好用，老头子也轻松多啦。;现在的年轻人这么能干，真是长江后浪推前浪啊。;#ch#要不要给这种改良的翻车起个什么名字？]],["taskText"]=[[#mz：先前在逍遥林采药的时候，遇到一个叫鹿鸣的小子，他说自己能改良翻车，要我过几日去看看。我正打算去看看呢。#ch#可否能给我放个假？]],["taskTitle"]=[[改良翻车]]},["shenshi021"]={["acceptText"]=[[YEL#mz：事不宜迟，咱们快些走吧！]],["chatId"]=[[chat001;chat002;chat006;chat015]],["chatId1"]=[[chat001;chat002;chat006;chat015]],["eventId"]=[[shenshi021]],["eventTalk"]=[[不知道我能不能在厨艺大会上夺魁。]],["id"]=[[shenshi021]],["lifeEvent"]=[[你见#mz平日除了做饭之外，还十分努力地钻研厨艺，一次闲聊之中，#mz告诉你他希望成为一名闻名天下的大厨，因而在不断努力之中。你虽然知道闻名天下并非一件十分容易的事，但还是对#mz表示支持。]],["lifeEvent1"]=[[我感觉离天下第一名厨越来越近了。;经过此次比赛，我感觉自己的厨艺还有诸多不足。;我学到了不少其他地方的菜式，等我掌握了就能烧给#ch#吃啦。]],["lifeText"]=[[HIY去扬州松鹤楼看仆人参加厨艺大赛。]],["lifeText1"]=[[出身市井小门小户，醉心于厨艺，以此为业。]],["lifeText2"]=[[出身市井小门小户，醉心于厨艺，以此为业。]],["lifeText3"]=[[出身市井小门小户，醉心于厨艺，以此为业，对提高自己的厨艺非常上心，甚至想成为天下第一名厨。]],["talkText"]=[[我打小便想当天下第一名厨，虽然现在的差距还有点远。;#ch#行走在外，一定能吃到不少地方的名菜，真好啊。;#ch#要是觉得什么菜好吃，可以记下来，下次我去找找菜谱做给你吃。]],["talktext1"]=[[我感觉离天下第一名厨越来越近了。;经过此次比赛，我感觉自己的厨艺还有诸多不足。;我学到了不少其他地方的菜式，等我掌握了就能烧给#ch#吃啦。]],["taskText"]=[[#mz：#ch#！我听说扬州城中新开了一家叫松鹤楼的酒楼，为了吸引客人，最近要举办一场厨艺大赛。我想前往参加，可以吗？]],["taskTitle"]=[[厨艺大赛]]},["shenshi022"]={["acceptText"]=[[YEL#mz：我就知道#ch#一定会答应！我这就去。]],["chatId"]=[[chat001;chat002;chat006;chat015]],["chatId1"]=[[chat001;chat002;chat006;chat015]],["eventId"]=[[shenshi022]],["eventTalk"]=[[能找到打菜刀的铁匠可真不容易。]],["id"]=[[shenshi022]],["lifeEvent"]=[[你和#mz聊了会天，谈到了做菜的心得，#mz表示自己平时做菜刀磨损得很快，很希望有一把好刀。只可惜如今铁匠铺大多愿意给江湖中人打造兵器，谁会愿意给一个小小厨子磨菜刀呢？谈至此处，#mz表示很想用你的兵器来试试切菜，被你十分嫌弃地推到一边。]],["lifeEvent1"]=[[我这把可是庖丁解牛刀！;果然有好刀做菜也会更加得心应手。;既然有了这把好刀，我也可以打消用#ch#的神兵切菜的念头了。]],["lifeText"]=[[HIY去金陵城帮助仆人找到铁匠打造菜刀。]],["lifeText1"]=[[积年老厨，做菜已经成了生命的一部分。]],["lifeText2"]=[[积年老厨，做菜已经成了生命的一部分。]],["lifeText3"]=[[积年老厨，做菜已经成了生命的一部分，有时候会脑洞大开，冒出一些惊人的想法。]],["talkText"]=[[都说好马配好鞍，宝剑配英雄，我们当厨子的，也想有一把好刀啊。;不知道拿#ch#的神兵来切菜是种怎样的感觉。;拿神兵切菜会不会把砧板也一起剁碎？]],["talktext1"]=[[我这把可是庖丁解牛刀！;果然有好刀做菜也会更加得心应手。;既然有了这把好刀，我也可以打消用#ch#的神兵切菜的念头了。]],["taskText"]=[[#mz：#ch#！我想去金陵城中找铁匠替我打造一把好的菜刀。#ch#能不能放我几天假？]],["taskTitle"]=[[庖丁菜刀]]},["shenshi023"]={["acceptText"]=[[YEL#mz：谢谢#ch#，若是能找到，那我一定做好菜给您吃。]],["chatId"]=[[chat001;chat002;chat006;chat015]],["chatId1"]=[[chat001;chat002;chat006;chat015]],["eventId"]=[[shenshi023]],["eventTalk"]=[[我想用石锅来做新菜。]],["id"]=[[shenshi023]],["lifeEvent"]=[[#mz平时对各大菜系十分有研究，说起来也是头头是道。你和#mz聊天之中，#mz表示想融合各地菜系的特色，做出一道不属于任何菜系的菜，只是如今只有想法，却没有好的办法。你对从未吃过的菜自然十分好奇，并表示对#mz十分支持。]],["lifeEvent1"]=[[#ch#要是喜欢我做的新菜，以后一定多做给你吃。;虽然创作新菜并非一件容易的事情，但这摸索的过程其实还挺令人开心。;#ch#喜欢闯荡江湖，我喜欢埋头烧菜，虽然志趣不同，但我们都做着自己喜欢做的事情，也算是同道中人了。]],["lifeText"]=[[HIY去大理石铺帮助仆人制造石锅。]],["lifeText1"]=[[积年老厨，做菜已经成了生命的一部分。]],["lifeText2"]=[[积年老厨，做菜已经成了生命的一部分。]],["lifeText3"]=[[积年老厨，做菜已经成了生命的一部分，对研究菜式有着巨大的热忱。]],["talkText"]=[[我最近在研究新的菜，要是能成，一定做给#ch#吃。;每个地方的菜系都有不同的偏好，有的好蒸，有的好炒，各地偏好不同，味道也是天差地别。;#ch#偏好何地的菜式？]],["talktext1"]=[[#ch#要是喜欢我做的新菜，以后一定多做给你吃。;虽然创作新菜并非一件容易的事情，但这摸索的过程其实还挺令人开心。;#ch#喜欢闯荡江湖，我喜欢埋头烧菜，虽然志趣不同，但我们都做着自己喜欢做的事情，也算是同道中人了。]],["taskText"]=[[#mz：古人烹饪，多为火炙石燔，如今有了锅子，就不再使用石器。我想重新使用石锅做菜，想去找找有没有能制作石锅的匠人。听说大理有一家石铺，我打算去看看。]],["taskTitle"]=[[石锅造饭]]},["shenshi024"]={["acceptText"]=[[YEL#mz：谢谢#ch#，好心会有好报的。]],["chatId"]=[[chat001;chat002;chat006;chat015]],["chatId1"]=[[chat001;chat002;chat006;chat015]],["eventId"]=[[shenshi024]],["eventTalk"]=[[天灾人祸已是可怜，这些人还吃不上饭。]],["id"]=[[shenshi024]],["lifeEvent"]=[[你和#mz聊了会天，闲聊之中聊到了#mz的过去，#mz幼年时家乡曾闹过饥荒，只有极少数人活了下来，而这些活下来的人当中大多吃了不应该吃的东西。正因为受过饥荒，#mz才立志成为一名厨子。你没想到#mz背后还有如此心酸的往事，一时间也不知道怎么出言安慰。]],["lifeEvent1"]=[[要是没有#ch#相助，我一个人也没法帮助那么多人，#ch#真是大善人。;我就是见不得人受苦挨饿，一定会尽量帮助，因此家里一直没什么积蓄，不过我并不后悔这么做。]],["lifeText"]=[[HIY和仆人一同去南阳为灾民施粥。]],["lifeText1"]=[[热衷厨艺，喜欢烹饪食物，是个知福惜福之人]],["lifeText2"]=[[热衷厨艺，喜欢烹饪食物，挨过饿受过苦，现在是个知福惜福之人]],["lifeText3"]=[[热衷厨艺，喜欢烹饪食物，挨过饿受过苦，现在是个知福惜福之人，把烹饪当成很神圣的事情，见不得别人挨饿。]],["talkText"]=[[#ch#生活顺风顺水，一定没见过人吃人的惨状。;虽然现在过上了好日子，但我还是希望这世上再没人挨饿。;#ch#要是觉得我做的菜好吃就多吃点。]],["talktext1"]=[[要是没有#ch#相助，我一个人也没法帮助那么多人，#ch#真是大善人。;我就是见不得人受苦挨饿，一定会尽量帮助，因此家里一直没什么积蓄，如今老大不小了，连讨媳妇的彩礼钱都没有。不过我并不后悔这么做。]],["taskText"]=[[#mz：前几日南阳城中发了水患，虽然已经及时遏制，但城中粮价飞涨，不少穷苦百姓都吃不起饭。我想带些粮食去那施粥，不知道#ch#许不许。]],["taskTitle"]=[[南阳救灾]]},["shenshi025"]={["acceptText"]=[[YEL#mz：我也不知道该不该去。]],["chatId"]=[[chat001;chat002;chat006;chat015]],["chatId1"]=[[chat001;chat002;chat006;chat015]],["eventId"]=[[shenshi025]],["eventTalk"]=[[她…果真嫁人了？]],["id"]=[[shenshi025]],["lifeEvent"]=[[#mz平时言语之间似乎藏有一段不为人知的过去，这日和你闲聊之中，#mz将这段过去都告诉了你。#mz少年时喜欢上了邻家的一名女子，那名女子似乎对#mz也有意，可两人年龄差距太大，#mz觉得不能耽误她终身，便不辞而别，离开家乡。你听罢，不禁心中感叹，这世上有多少有情人，因为世俗的眼光不能走到一起，着实令人惋惜。]],["lifeEvent1"]=[[没想到我这么多年未娶，她竟也这么多年未嫁。;我们已经决定结为夫妻，到时候还要给#ch#敬一杯喜酒。;再过不久她也要从老家搬过来了，真令人高兴。]],["lifeText"]=[[HIY同仆人一起去汝州参加王家小姐婚宴。]],["lifeText1"]=[[来自异乡，不知从何时辗转来到此地，以厨艺为立身之本。]],["lifeText2"]=[[来自异乡，不知从何时辗转来到此地，以厨艺为立身之本。]],["lifeText3"]=[[在厨子烟熏火燎的外表下，藏着一颗情种的心。]],["talkText"]=[[#ch#别看我长这样，从前也是有心爱之人的。;当年的她尚年幼，可能她自己都不知道那是对兄长的喜欢还是真正的爱慕。;一晃已经多少年了？我也不记得多少年了。]],["talktext1"]=[[没想到我这么多年未娶，她竟也这么多年未嫁。;我们已经决定结为夫妻，到时候还要给#ch#敬一杯喜酒。;再过不久她也要从老家搬过来了，真令人高兴。]],["taskText"]=[[#mz：听说，她家最近在办红事，我…我还是想去看看她。她家住在汝州，离此地不算近，来去要花些时日，所以想和#ch#告几天假。]],["taskTitle"]=[[汝州喜宴]]},["shenshi026"]={["acceptText"]=[[YEL#mz：#ch#您就行行好，帮帮我这一次，成吗？]],["chatId"]=[[chat002;chat010;chat016]],["chatId1"]=[[chat002;chat010;chat016]],["eventId"]=[[shenshi026]],["eventTalk"]=[[真想见一面欧冶子前辈。]],["id"]=[[shenshi026]],["lifeEvent"]=[[#mz边打铁边和你聊了起来，#mz知道你有不少神兵，认识不少匠人，便问你认不认识欧冶子。#mz小时候便向往着欧冶子的传说，长大后也因此成为一名铁匠。虽然欧冶子并没有#mz想象的那么神，但看到#mz憧憬的样子，你还是决定有机会帮#mz见上欧冶子一面。]],["lifeEvent1"]=[[我真的见到欧冶子本尊了？我是不是在做梦？#ch#您掐我一把？哎哟，您还真下手啊。;我更加坚定了成为一名匠人的决心。;希望有朝一日我能为#ch#铸造一柄盖世无双的神兵。]],["lifeText"]=[[HIY去华山助仆人见欧冶子一面。]],["lifeText1"]=[[匠户出身，为人看起来谦恭和善。]],["lifeText2"]=[[匠户出身，为人看起来谦恭和善。]],["lifeText3"]=[[匠户出身，为人看起来谦恭和善，对提高自己的手艺十分热切。]],["talkText"]=[[#ch#，#ch#！您有那么多兵器，肯定认识不少铁匠？那您认识那位闻名天下的欧冶子吗？;我也想成为欧冶子那样的大师。;虽然现在天下闻名的锻造大师不少，但还是欧冶子最为传奇。]],["talktext1"]=[[我真的见到欧冶子本尊了？我是不是在做梦？#ch#您掐我一把？哎哟，您还真下手啊、;我更加坚定了成为一名匠人的决心。;希望有朝一日我也能为#ch#铸造神兵。]],["taskText"]=[[#mz：我听说欧冶子前辈会在这几日去华山纪念故人。我想去亲眼见上传说中的锻造大师一面，但这样未免唐突。#ch#您一定认识欧冶子前辈，您能帮我撮合撮合吗？]],["taskTitle"]=[[憧憬之人]]},["shenshi027"]={["acceptText"]=[[YEL#mz：那我去去就来。]],["chatId"]=[[chat002;chat010;chat016]],["chatId1"]=[[chat002;chat010;chat016]],["eventId"]=[[shenshi027]],["eventTalk"]=[[希望赵先生能修好我的断剑。]],["id"]=[[shenshi027]],["lifeEvent"]=[[你和#mz闲聊起来，聊到了#mz的过去，#mz说小时候时常自己动手做一些刀剑之物，虽然都是木制，但也为后来成为铁匠打下基础。只是#mz幼年时最喜欢的一把木剑后来折断了，#mz一直留在身边想修复这把剑，却不知道木质该如何修复。]],["lifeEvent1"]=[[竟然能想到这种修补办法，匠人的智慧真是不可小觑。;我没法修补木剑，别人却可以，看来我的手艺还有待精进。;这把木剑虽然再寻常不过，却是我我幼时最重要的东西。我一定会好好珍藏它。]],["lifeText"]=[[HIY去苏州帮仆人找寻赵弥生修补断剑。]],["lifeText1"]=[[出身贫寒，很早就自食其力、以打铁为生。]],["lifeText2"]=[[出身贫寒，很早就自食其力、以打铁为生，几经漂泊，现在终于安定下来。]],["lifeText3"]=[[出身贫寒，很早就自食其力、以打铁为生，几经漂泊，随着生活逐渐安定下来，有时也会怀念去过去的人和事。]],["talkText"]=[[小时候家里穷，玩具都是自己做，可能就是因为这样才当了一个铁匠。;我小时候想当一名大将军，保家卫国。#ch#小时候想当什么呢？;成人之后，人就特别容易怀旧。]],["talktext1"]=[[竟然能想到这种修补办法，匠人的智慧真是不可小觑。;我没法修补木剑，别人却可以，看来我的手艺还有待精进。;这把木剑虽然再寻常不过，但却是我我幼时最重要的东西。我一定会好好珍藏它。]],["taskText"]=[[#mz：我听说落月山庄的赵弥生这些日子在苏州城中游历，赵弥生锻造技艺高超，我想去找找他替我修补这把木剑。#ch#能否放我几天假？]],["taskTitle"]=[[断剑修补]]},["shenshi028"]={["acceptText"]=[[YEL#mz：多谢#ch#。]],["chatId"]=[[chat002;chat010;chat016]],["chatId1"]=[[chat002;chat010;chat016]],["eventId"]=[[shenshi028]],["eventTalk"]=[[如若可以，真不想再回去。]],["id"]=[[shenshi028]],["lifeEvent"]=[[#mz对铸造术十分了解，且知道不少铸造大师的事。你觉得#mz似乎师出名门，一时也十分好奇#mz师父到底是谁。一日你向#mz提起此事，#mz开始时称自己都是书上学来，见你不信，犹豫半晌之后，还是向你吐露了真相。原来#mz本是唐门弟子，唐阡陌禁止弟子再铸剑之后，#mz不想看到这门手艺就此没落，便偷偷逃了出来，隐姓埋名当了一名铁匠。]],["lifeEvent1"]=[[唐门铸剑术毕竟也传承百年，不能就这样失传。;家主其实也不想唐门铸造术失传，所以才会对我的事睁一只眼闭一只眼吧。;只可惜往后铸剑都不能以唐门中人自称。]],["lifeText"]=[[HIY去唐门助仆人取回旧物。]],["lifeText1"]=[[看不出来是何方人氏，谈吐得体，思维敏捷，非一般铁匠可比。]],["lifeText2"]=[[作为铁匠，技艺精湛，拥有的理论知识丰富，看出来是一套很自成体系的传承，看来是系出名门。]],["lifeText3"]=[[出自唐门的铸剑师，委身于铁匠一职，为的是唐门铸剑的技艺和传承能够流传下去。]],["talkText"]=[[闻名天下的铸剑师太多了，都是我们铁匠憧憬的对象。;西绝华山沐清风，南隐唐门唐阡陌，北水之巅轩辕生，这三人均是曾闻名天下的铸剑师，#ch#有没有听说过？;我的铸造术也算是出自名门了吧。]],["talktext1"]=[[唐门铸剑术毕竟也传承百年，不能就这样失传。;家主其实也不想唐门铸造术失传，所以才会对我的事睁一只眼闭一只眼吧。;只可惜往后铸剑都不能以唐门中人自称。]],["taskText"]=[[#mz：#ch#，我要去唐门取回一件以前的东西，想给#ch#告几天假。]],["taskTitle"]=[[唐门旧事]]},["shenshi029"]={["acceptText"]=[[YEL#mz：多谢#ch#！我这就去收拾行李。]],["chatId"]=[[chat002;chat010;chat016]],["chatId1"]=[[chat002;chat010;chat016]],["eventId"]=[[shenshi029]],["eventTalk"]=[[希望能找到会打造双环之人。]],["id"]=[[shenshi029]],["lifeEvent"]=[[你和#mz闲聊起来，#mz对最近江湖之上盛行的双环十分感兴趣，但会锻造的铁匠比较少，#mz也不知道该如何入手比较好。你心里也想着帮#mz一把，便找来锻造书籍说给#mz听，#mz表示对你十分感激。]],["lifeEvent1"]=[[双环果然不好锻造呐。;这次锻造对我来说是一次十分宝贵的经验。;下次要不要再尝试打点别的兵器？]],["lifeText"]=[[HIY去大理帮助仆人寻找会锻造双环的匠人。]],["lifeText1"]=[[匠户出身，醉心于打铁和各种铸造工艺。]],["lifeText2"]=[[匠户出身，醉心于打铁和各种铸造工艺。]],["lifeText3"]=[[匠户出身，醉心于打铁和各种铸造工艺，希望能够尝试打造更多类型的兵器。]],["talkText"]=[[我最近想尝试锻造一把厉害的兵器。可惜我大字不识几个，不然借#ch#的锻造书看看说不定能有所收获。;双环使用独特，想要锻造出上佳的双环并不是一件容易的事]],["talktext1"]=[[双环果然不好锻造呐。;这次锻造对我来说是一次十分宝贵的经验。;下次要不要再尝试打点别的兵器？]],["taskText"]=[[#mz：都说绝地多奇人，大理城地处西南，与世隔绝，想来奇人异士也不少。我想去大理几日，找找有没有人会锻造双环武器，因而想跟#ch#告个假。]],["taskTitle"]=[[奇兵双环]]},["shenshi030"]={["acceptText"]=[[YEL#mz：真是多谢#ch#了。看我不好好教训他。]],["chatId"]=[[chat002;chat010;chat016]],["chatId1"]=[[chat002;chat010;chat016]],["eventId"]=[[shenshi030]],["eventTalk"]=[[我这不争气的弟弟，真是让人操碎了心。]],["id"]=[[shenshi030]],["lifeEvent"]=[[#mz平时时常提到#mz的弟弟，在你两人闲聊之际，#mz将#mz弟弟的事情都告诉了你。#mz父母膝下只有两个孩子，#mz以打铁为业，而#mz弟弟整日游手好闲，不学无术。#mz父母因为弟弟的事整日操碎了心，有意让#mz教授其打铁，可#mz弟弟吃不了苦，不愿学习。#mz现在对这个弟弟也没什么好办法，只得帮他留心有没有适合的事做。]],["lifeEvent1"]=[[那臭小子经过这次教训，想必也该长大了。;我弟弟虽然称不上痛改前非，但也确实勤勉了不少，这都要多亏#ch#啊。;现在弟弟省心多了，爹娘就开始操心起我的婚事了。]],["lifeText"]=[[HIY去扬州兵营看看仆人弟弟出了什么事。]],["lifeText1"]=[[出身小康之家，从事铁匠已经有好些年了。]],["lifeText2"]=[[出身小康之家，从事铁匠已经有好些年了，在这行当里小有名声。最大的烦恼似乎来自他不成器的弟弟。]],["lifeText3"]=[[从事铁匠已经有好些年了，在这行当里小有名声。最大的烦恼似乎来自他不成器的弟弟。一心想让弟弟走上正途，自己也可以找到衣钵传人。]],["talkText"]=[[我家人丁稀薄，爹娘只有我和弟弟两个孩子，弟弟又是个不争气的。;我现在还没有婚娶，这打铁的技艺也不知道教给谁。;在外务工啊，家里什么事情都放得下，就是放心不下我弟弟。]],["talktext1"]=[[那臭小子经过这次教训，想必也该长大了。;我弟弟虽然称不上痛改前非，但也确实勤勉了不少，这都要多亏#ch#啊。;现在弟弟省心多了，爹娘就开始操心起我的婚事了。]],["taskText"]=[[#mz：方才爹娘来说我弟弟出了事，被暂时关押在扬州兵营之中。我想离开一阵去解决那臭小子的事，不知道#ch#同不同意。]],["taskTitle"]=[[不肖子弟]]},["shenshi031"]={["acceptText"]=[[YEL#mz：多谢#ch#！]],["chatId"]=[[chat003;chat004;chat017;chat018]],["chatId1"]=[[chat003;chat004;chat017;chat018]],["eventId"]=[[shenshi031]],["eventTalk"]=[[等我去京城置办点东西，就能回去一趟了。]],["id"]=[[shenshi031]],["lifeEvent"]=[[你和#mz在交手之余，发现#mz是一个很容易相处的人，一来二去，#mz将你视为朋友，并告诉了你自己的过去。#mz少年时因看不惯乡里的一个恶人，便将其杀死，被抓获之后，衙门判罚#mz流放大漠。#mz在大漠呆了五年，后来找机会逃走，从此隐姓埋名地生活。#mz既然肯把这种杀头之罪告诉你，足以见得对你已是十分信任。]],["lifeEvent1"]=[[等我将来老了，再去大漠隐居也是不错。;我这辈子也没啥追求，能有#ch#这般交心之友已经死而无憾了。;前些日子去了一趟大漠，那里一点也没变。]],["lifeText"]=[[HIY去京城帮助仆人置办前去大漠的行李。]],["lifeText1"]=[[来历神秘，眼神中透着灵醒和热情，看起来也是个有故事的人。]],["lifeText2"]=[[为人和善，但看起来也是个有故事的人，似乎带有案底。]],["lifeText3"]=[[虽然带有案底，但本质上是个对朋友交心、富有正义感的良善之人。]],["talkText"]=[[要是我拿出真本事来，#ch#也不一定是我的对手呢，哈哈。;离开大漠久了，偶尔也会想念大漠的无限风光。;#ch#想要我陪练，大可不必手下留情，一个已经死过一次的人，哪里还会在乎些许皮肉之苦。]],["talktext1"]=[[等我将来老了，再去大漠隐居也是不错。;我这辈子也没啥追求，能有#ch#这般交心之友已经死而无憾了。;虽然离开大漠已经多年，但那里的样子一点没变。]],["taskText"]=[[#mz：过些日子我打算回大漠去看一看。我会先去京城置办点东西，#ch#要是想一同游玩，可来京城找我。]],["taskTitle"]=[[大漠风光]]},["shenshi032"]={["acceptText"]=[[YEL#mz：那我就先去了。]],["chatId"]=[[chat003;chat004;chat017;chat018]],["chatId1"]=[[chat003;chat004;chat017;chat018]],["eventId"]=[[shenshi032]],["eventTalk"]=[[也不知道此时取出拳法适合不适合。]],["id"]=[[shenshi032]],["lifeEvent"]=[[#mz平时工作勤勉，似乎对武学也十分感兴趣，但总是抓不到诀窍。你发现#mz的武功路数之间似乎有你完全没见过的招式，询问之下，#mz告诉你自己爷爷曾也是武林中人，还自创了一套拳法，但这拳法奥妙精深，#mz天资愚钝，无法领悟，恐怕这拳法就要葬送在自己手上。]],["lifeEvent1"]=[[虽然我比较愚钝，但现在也能领悟一些爷爷的拳法了，这都要多谢#ch#的提点。;我爹对武学毫无悟性，幸好我还能学会爷爷的武功，不然我们家可算断了传承了。;我对拳法已经掌握一二，#ch#什么时候有空，咱们可以切磋一番。]],["lifeText"]=[[HIY去华山帮仆人找回半部拳法。]],["lifeText1"]=[[似乎是家学渊源，有一定的武学基础]],["lifeText2"]=[[家学渊源，有一定的武学基础，对武学之道相当痴迷。]],["lifeText3"]=[[出身于没落的武学世家，肩负着传承家传武学的重任。]],["talkText"]=[[我要是习武的造诣和#ch#您一样高就好了。;#ch#您武功日益精进，我看了也替您高兴。我要是能有您一半优秀就好了。;#ch#要是闲暇时候能对我指点一二，那可真是天大的福气。]],["talktext1"]=[[虽然我比较愚钝，但现在也能领悟一些爷爷的拳法了，这都要多谢#ch#的提点。;我爹对武学毫无悟性，幸好我还能学会爷爷的武功，不然我们家可算断了传承了。;我对拳法已经掌握一二，#ch#什么时候有空，咱们可以切磋试试。]],["taskText"]=[[#mz：爷爷生前只传授了我拳法上半部，下半部他埋在了华山玉女峰之上，让我在合适的时候去取回。我想现在就去把拳法取回，想跟#ch#告个假。]],["taskTitle"]=[[半部拳法]]},["shenshi033"]={["acceptText"]=[[YEL#mz：好，她现在在扬州，我们快走吧！]],["chatId"]=[[chat003;chat004;chat017;chat018]],["chatId1"]=[[chat003;chat004;chat017;chat018]],["eventId"]=[[shenshi033]],["eventTalk"]=[[我绝不能让她落入青楼。]],["id"]=[[shenshi033]],["lifeEvent"]=[[#mz时常提起自己的青梅竹马，似乎两人关系十分要好。和你的闲聊之间，#mz将他们俩的事情告诉了你，那位邻居的父亲败破家财，又欠下一屁股债，整日借酒消愁，又对自己女儿拳脚相向。#mz心中也因此而烦闷。]],["lifeEvent1"]=[[一个人到底有多狠的心，才会毫不犹豫地把自己亲生女儿卖到青楼？;我以后都会对她好，绝不让她再受到委屈。;#ch#助我将她救出，对我恩重如山，我以后都会好好报答#ch#。]],["lifeText"]=[[HIY帮助#mz前往扬州青楼救回青梅竹马。]],["lifeText1"]=[[我和她打小一起长大，引以为知己。]],["lifeText2"]=[[她爹如此待她，真是让人看的生气。]],["lifeText3"]=[[我有个一同长大的邻居，关系十分要好。]],["talkText"]=[[一个人到底有多狠的心，才会毫不犹豫地把自己亲生女儿卖到青楼？;她在这世上无依无靠，只有我能照顾她了。;老爷助我将她救出，对我恩重如山，我以后都会好好报答老爷。]],["talktext1"]=[[一个人到底有多狠的心，才会毫不犹豫地把自己亲生女儿卖到青楼？;我以后都会对她好，绝不让她再受到委屈。;#ch#助我将她救出，对我恩重如山，我以后都会好好报答#ch#。]],["taskText"]=[[#mz：#ch#，我有一事相求，请您一定要答应！昨日我得到消息，我的青梅竹马被她爹卖到了青楼，今日便要送去，要是我不去救她出来，她，她就…]],["taskTitle"]=[[青楼救人]]},["shenshi034"]={["acceptText"]=[[YEL#mz：好的。我师父也曾是江湖中人，想来对#ch#的事也很感兴趣，我定会将#ch#的事说给我师父听。]],["chatId"]=[[chat003;chat004;chat017;chat018]],["chatId1"]=[[chat003;chat004;chat017;chat018]],["eventId"]=[[shenshi034]],["eventTalk"]=[[师父他老人家不知现在如何了。]],["id"]=[[shenshi034]],["lifeEvent"]=[[你与#mz闲聊起来，得知#mz原本来自一座小村庄，村中有一名老者开了一家武馆，#mz的本事都是和那老者学来。你听#mz描述那老者事迹，感觉到那老者并非寻常人，恐怕是什么高人退隐江湖之后居住在那，一时也心向往之，期盼能见上那老者一面。]],["lifeEvent1"]=[[原来师父他真的是个高人，能做他徒弟真是上天的恩赐。;我也要努力练功，不能丢我师父的脸。师父他不希望被人打扰，还请#ch#对这件事保密。]],["lifeText"]=[[HIY去华山村看看仆人师父究竟为何人。]],["lifeText1"]=[[来自一个偏远小山村，一身武艺不知学自何人。]],["lifeText2"]=[[来自一个偏远小山村，一身武艺不知学自何人。]],["lifeText3"]=[[来自一个偏远小山村，一身武艺学自师傅：一个隐居在小村子里的老者。]],["talkText"]=[[出来也有些日子了，不知道师父他老人家过得怎么样。;我这一身本事都是我师父教的，师父在村子里也算是有名的武馆教头。;听说世外高人都喜欢隐居在小村落，师父是不是也是这种人？]],["talktext1"]=[[原来师父他真的是个高人，能做他徒弟真是上天的恩赐。我也要努力练功，不能丢我师父的脸。;师父他不希望被人打扰，还请#ch#对这件事保密。;师父上次见过#ch#之后，一直夸您骨骼惊奇，将来一定有一番大作为。]],["taskText"]=[[#mz：#ch#，我想回华山村看看我师父，能否跟您告个假？]],["taskTitle"]=[[世外高人]]},["shenshi035"]={["acceptText"]=[[YEL#mz：#ch#深明大义，多谢了。]],["chatId"]=[[chat003;chat004;chat017;chat018]],["chatId1"]=[[chat003;chat004;chat017;chat018]],["eventId"]=[[shenshi035]],["eventTalk"]=[[我绝不能让他们做傻事。]],["id"]=[[shenshi035]],["lifeEvent"]=[[你和#mz聊天的过程中，发现#mz十分不拘小节，#mz告诉你自己出生草莽，本是占山为王的山贼，后来脱离山寨，洗手不干，才来做了陪练的营生。刀口混饭吃多年，#mz家中积蓄不少，对陪练的工钱也不是特别看重，只希望能平静度日。]],["lifeEvent1"]=[[虽然以前的同伴们仍旧过着杀人放火的生活，我还是不能报官将他们抓去，毕竟相识一场，只希望他们往后能幡然醒悟，洗心革面重新做人。;#ch#不用对我发太多工钱，我家里积蓄不少，这些钱你可以留着给别人。;希望#ch#也不要报官抓他们，他们本性都不坏，只是被生活逼迫成了这样。]],["lifeText"]=[[HIY和仆人一同去南阳阻止山贼抢劫官银。]],["lifeText1"]=[[出身不明，身上带着一丝草莽气，想必也曾是江湖儿女。]],["lifeText2"]=[[出身不明，身上带着一丝草莽气，想必也曾是江湖儿女。]],["lifeText3"]=[[当过山贼，如今改邪归正，洗心革面。]],["talkText"]=[[有时候真怀念从前那般大碗喝酒大口吃肉的日子。;要是让我重走一遭，我做过的事，我说过的话，都不会后悔。;想当年老…我也是刀口上讨生活的人。]],["talktext1"]=[[虽然以前的兄弟们仍旧过着杀人放火的生活，我还是不能报官将他们抓去，毕竟兄弟一场，只希望他们往后能幡然醒悟，洗心革面重新做人。;#ch#不用对我发太多工钱，我家里积蓄不少，这些钱你可以留着给别人。;希望#ch#也不要报官抓他们，他们本性都不坏，只是被生活逼迫成了这样。]],["taskText"]=[[#mz：我以前的兄弟们打算去南阳截官府的货，还想拉我入伙，我没同意。抢官银可是杀头的重罪，我想要去阻止他们，想跟#ch#告个假。]],["taskTitle"]=[[不义之财]]},["shenshi036"]={["acceptText"]=[[YEL#mz：多谢。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi036]],["eventTalk"]=[[血海深仇未报，令人寝食难安。]],["id"]=[[shenshi036]],["lifeEvent"]=[[#mz平日里除了必要的交流和你主动找#mz说话之外，从来不会主动找你谈话，都是有多远躲多远。你对其态度略有不满，找到#mz谈及此事，#mz一开始并不愿意告诉你原因，后来在你的软磨硬泡之下，才得知#mz家从前也是武林大家，因招惹仇家，家人大多被杀，#mz不得已才逃了出来，寄人篱下。]],["lifeEvent1"]=[[大仇得报，我心愿已了。仔细想来，这里好吃好喝，也挺不错的，我就暂时跟着你吧。;…#ch#。唔，这称呼真是别扭。;难得今天没事，不如一起聊聊天。]],["lifeText"]=[[HIY去南阳助仆人复仇。]],["lifeText1"]=[[来历不明，身手高强，似乎在逃避什么。]],["lifeText2"]=[[来历不明，身手高强，似乎在逃避什么。身上有着一些世家子弟的影子。]],["lifeText3"]=[[出身武林世家，背负血海深仇。]],["talkText"]=[[你出钱，我办事，咱们是合作关系，并非主仆。;总有一日我要叫他们血债血偿。;寄人篱下，身不由己。]],["talktext1"]=[[大仇得报，我心愿已了。仔细想来，这里好吃好喝，也挺不错的，我就暂时跟着你吧。;老…#ch#。唔，这称呼真是别扭。;难得今天没事，不如一起聊聊天。]],["taskText"]=[[#mz：我要离开些时日。若是我不能回来…劳烦你去南阳替我收尸。]],["taskTitle"]=[[南阳复仇]]},["shenshi037"]={["acceptText"]=[[YEL#mz：那我便去了。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi037]],["eventTalk"]=[[爹的遗愿，我一定会想办法达成。]],["id"]=[[shenshi037]],["lifeEvent"]=[[你和#mz聊了会天，了解到#mz家父本是少林弟子，因和来上香的女子产生情愫，才还了俗。#mz一家虽然美满和睦，父亲也是无疾而终，但未能服侍在师父身边成了#mz父亲此生最大的遗憾。你听罢，想到人贪恋红尘一世，沉沦其中，错对难分，真正能看破红尘者又有几人？ 心下便忍不住感叹起来。]],["lifeEvent1"]=[[少林寺既然原谅了父亲，我想父亲他在九泉之下若能有知，也能了却心愿了。;经此一事，我突然觉得，等我将来老了皈依我佛，伴青灯长眠，聆莲花妙语，也并非坏事。;虽然我爹一时鬼迷心窍盗走了秘籍，但他从来没有学过，也没有教过我，想来也对这件事颇为后悔。]],["lifeText"]=[[HIY和仆人一起去少林归还被盗的秘籍。]],["lifeText1"]=[[武功路数刚猛、大气，据说传自其父亲。]],["lifeText2"]=[[武功路数刚猛、大气，据说传自其父亲。]],["lifeText3"]=[[其父本是少林寺弟子，和少林寺有着极深的渊源。]],["talkText"]=[[我爹原本是少林寺的僧人，后来遇见了我娘，便还了俗成了家。;若是我爹还健在，一定很想去少林看看吧。;我爹这辈子最大的遗憾，就是没能报答他师父的养育之恩。]],["talktext1"]=[[少林寺既然原谅了父亲，我想父亲他在九泉之下若能有知，也能了却心愿了。;经此一事，越发觉得少林的好，等我将来老了皈依我佛，伴青灯长眠，聆莲花妙语，也并非坏事。;虽然我爹一时鬼迷心窍盗走了秘籍，但他从来没有学过，也没有教过我，想来也对这件事颇为后悔。]],["taskText"]=[[#mz：父亲曾在少林寺盗取秘籍带出，后来一直很后悔此事。我想要去少林寺归还秘籍，想暂时离开几天。]],["taskTitle"]=[[秘籍归还]]},["shenshi038"]={["acceptText"]=[[YEL#mz：好的，谢谢#ch#。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi038]],["eventTalk"]=[[小五收到礼物一定很高兴。]],["id"]=[[shenshi038]],["lifeEvent"]=[[你和#mz聊起天来，言语之中你察觉到#mz似乎极为喜欢孩童。#mz告诉你自己小时候是孤儿，被一户人家收养长大，才有今天的成就。自那之后，#mz就决定帮助更多的孤儿，让他们也能有个庇护之所。现在虽然日子清苦了些，但#mz也因此有了更多的牵挂之人。你听罢，被#mz的善心所感动。]],["lifeEvent1"]=[[小五现在比从前开朗多了，我真替他感到高兴。;自那次之后孩子们都挺想念#ch#的。;下次再去京城，一定请#ch#去千金楼喝酒。]],["lifeText"]=[[HIY去京城帮助仆人挑选生辰礼物。]],["lifeText1"]=[[从小便是孤儿，被人收养长大。]],["lifeText2"]=[[成人之后心地善良，对是孤儿的孩子抱有怜悯之心。]],["lifeText3"]=[[因为对孤儿的怜悯之心，收养了不少同样身世可怜的孩子。]],["talkText"]=[[您喜欢孩子吗？;若是我以后成亲了，定然也会很疼爱自己的孩子。;有些孩子无父无母，身世可怜，若是无人照顾，大多只有饿死街头的下场。]],["talktext1"]=[[小五现在比从前开朗多了，我真替他感到高兴。;自那次之后孩子们都挺想念#ch#的。;下次再去京城，一定请#ch#去千金楼喝酒。]],["taskText"]=[[#mz：#ch#，我，我请个假，去一趟京城杂货店办点私事。成吗？]],["taskTitle"]=[[生辰之礼]]},["shenshi039"]={["acceptText"]=[[YEL#mz：好呀，一起去。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi039]],["eventTalk"]=[[制陶需要好土。]],["id"]=[[shenshi039]],["lifeEvent"]=[[你和#mz闲聊起来，你发现#mz对制陶颇有心得，对#mz的身世也越发好奇。#mz告诉你祖上都是陶艺匠人，制陶的手艺代代传承，到自己这一代已经是第九代。#mz打小对制陶便十分感兴趣，再加上天资聪颖，如今已经是制陶好手。]],["lifeEvent1"]=[[既然人称我为陶匠，我便要更加精进，才能对得起这个匠字。;比起老祖宗们的手艺，我还差得远呐。;#ch#对我的手艺可喜欢？]],["lifeText"]=[[HIY和仆人一起去逍遥林找到能制陶的泥土。]],["lifeText1"]=[[本是江湖儿女，目前已经洗尽铅华，追求平淡的生活。]],["lifeText2"]=[[本是江湖儿女，目前已经洗尽铅华，追求平淡的生活，对制陶似乎有着异乎常人的喜爱。]],["lifeText3"]=[[祖上是陶匠艺人，家学渊源，称得上制陶好手。]],["talkText"]=[[#ch#喜欢陶艺吗？要是喜欢，改日我做些小物件送给你玩。;现在富人都以追求瓷器为风尚，陶器就成为穷人的象征。其实一件好的陶器制作工艺繁琐复杂，精美程度也不比瓷器差。;比起在江湖上打打杀杀，我倒是更喜欢过点宁静日子。]],["talktext1"]=[[既然人称我为陶匠，我便要更加精进，才能对得起这个匠字。;比起老祖宗们的手艺，我还差得远呐。;#ch#对我的手艺可喜欢？]],["taskText"]=[[#mz：我正打算去逍遥林挖些泥土来制陶。#ch#要不要一起来？]],["taskTitle"]=[[制陶匠人]]},["shenshi040"]={["acceptText"]=[[YEL#mz：多谢#ch#！]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi040]],["eventTalk"]=[[买什么古籍好呢。]],["id"]=[[shenshi040]],["lifeEvent"]=[[你和#mz聊起了天，#mz虽然是江湖中人，却十分羡慕那些饱读诗书的文人。#mz自己表示只认得几个字，对舞文弄墨一事一窍不通，有心想去私塾求学，但挤在一群孩子之中又觉得不太好意思，只得背地里偷偷买些书籍来看。你见#mz真心向学，便表示若是有读不懂的地方可以来询问自己，#mz听了，对你十分感激。]],["lifeEvent1"]=[[最近对读书稍微有点心得了，这都是#ch#的功劳。;人说书中自有黄金屋，诚不欺我。;我觉得读书可比闯荡江湖要有趣多了。]],["lifeText"]=[[HIY去扬州看看仆人买什么古籍。]],["lifeText1"]=[[出身草莽，胸无点墨，却有一颗向学之心。]],["lifeText2"]=[[出身草莽，胸无点墨，却有一颗向学之心。]],["lifeText3"]=[[出身草莽，胸无点墨，却有一颗向学之心，算不上读书种子，却也十分难得。]],["talkText"]=[[真羡慕那些文质彬彬的读书人。;像我这种粗人，认得几个字就不错了，那些高深的道理我也不怎么懂。;我也去弄几本书来读读，长长见识。]],["talktext1"]=[[最近对读书稍微有点心得了，这都是#ch#的功劳。;人说书中自有黄金屋，诚不欺我。;我觉得读书可比闯荡江湖要有趣多了。]],["taskText"]=[[#mz：我听说扬州城中有人在出售很多古书籍，都是难得一见的珍品，我也想去看看，或许能买上几本。能否跟#ch#告个假？]],["taskTitle"]=[[购买古籍]]},["shenshi041"]={["acceptText"]=[[YEL#mz：那穆老爷在金陵城经营有一家钱庄，咱们往那去寻他，都仰仗#ch#您了。]],["chatId"]=[[chat001;chat002;chat003;chat019]],["chatId1"]=[[chat001;chat002;chat003;chat019]],["eventId"]=[[shenshi041]],["eventTalk"]=[[穆老爷定然不会轻易将卖身契给我。]],["id"]=[[shenshi041]],["lifeEvent"]=[[#mz一直愁眉不展，似乎和#mz的身世有关。#mz和你闲聊之中向你谈及此事，#mz家中贫穷，父母在自己很小的时候，便将我卖给了大户人家做下人。虽然现在#mz在你这里做事，但#mz的卖身契仍旧掌握在那户人家手里，#mz永远都是奴籍，无法翻身。]],["lifeEvent1"]=[[谢谢#ch#帮我要回了卖身契，虽然我现在已经不再是奴籍，但我还是愿意做您的下人。;以前从来没有这么开心过。]],["lifeText"]=[[HIY去金陵城钱庄为仆人讨回卖身契。]],["lifeText1"]=[[出身贫寒。]],["lifeText2"]=[[出身贫寒，似乎至今仍是奴籍。]],["lifeText3"]=[[出身贫寒，身世可怜。]],["talkText"]=[[小时候家里穷，爹娘就狠心把我卖给了大户人家。;一日为奴终身为奴，这种任人宰割的滋味，#ch#这种人上人是没法懂的。;何时才是个头啊。]],["talktext1"]=[[谢谢#ch#帮我要回了卖身契，虽然我现在已经不再是奴籍，但我还是愿意做您的下人。;以前从来没有这么开心过。]],["taskText"]=[[#mz：爹娘在我小时候把我卖给了穆老爷，我的卖身契也在他那。要是这卖身契不寻回来，我也一辈子没法翻身。#ch#能否看在我服侍您多日的份上，替我讨回卖身契？]],["taskTitle"]=[[寻回契约]]},["shenshi042"]={["acceptText"]=[[YEL#mz：太好啦！那咱们快去扬州找他！]],["chatId"]=[[chat001;chat002;chat003;chat019]],["chatId1"]=[[chat001;chat002;chat003;chat019]],["eventId"]=[[shenshi042]],["eventTalk"]=[[西域的菜，定然和中原不同。真想尝一尝。]],["id"]=[[shenshi042]],["lifeEvent"]=[[#mz是一个十分喜欢吃的人，也吃过不少各地的美食。你和#mz闲聊之中，聊到了各地的美食，#mz听得津津有味，眼中冒出精光。你见#mz馋成这样，也觉得好笑。]],["lifeEvent1"]=[[啊，太好吃啦。;我的追求就是尝遍天下美味。;虽然异邦的菜很有独特的味道，但还是咱们华夏的菜好吃。]],["lifeText"]=[[HIY去扬州城帮仆人找到西域大厨。]],["lifeText1"]=[[小户人家出身，性情温良。]],["lifeText2"]=[[小户人家出身，性情温良。]],["lifeText3"]=[[小户人家出身，性情温良，对美食有着异乎常人的爱好，是个十足的老饕。]],["talkText"]=[[啊，什么时候开饭？;好想吃烤鸭肘子烧鸡醋鱼…;刚才门外是不是有人在卖糖葫芦？]],["talktext1"]=[[啊，太好吃啦。;我的追求就是尝遍天下美味。;虽然异域的菜很有独特的味道，但还是咱们华夏的菜好吃。]],["taskText"]=[[#mz：听说扬州城中来了个西域的厨子，做的都是西域的菜，但这厨子性情古怪，请他做菜都要跟他来什么猜谜，我对猜谜一点都不擅长，但我又很想吃他做的菜，我知道#ch#聪慧，能不能请#ch#你去和他猜谜？]],["taskTitle"]=[[西域美食]]},["shenshi043"]={["acceptText"]=[[YEL#mz：多谢#ch#。]],["chatId"]=[[chat001;chat002;chat003;chat019]],["chatId1"]=[[chat001;chat002;chat003;chat019]],["eventId"]=[[shenshi043]],["eventTalk"]=[[我不会毁约的。]],["id"]=[[shenshi043]],["lifeEvent"]=[[你和#mz闲聊起来，聊到了#mz小时候的事，#mz儿时有一个很好的玩伴，两人都梦想着长大后能成为行侠仗义的大侠，并约定长大后一定来一场大侠之间的比武。多年过去，#mz终究没能成为大侠，儿时的玩伴也早已背井离乡，失去了音讯。]],["lifeEvent1"]=[[希望我的孩子将来能成为大侠。;我们中的很多人，最后都会活成自己曾经最讨厌的样子。;儿时的赌约，是我输了。]],["lifeText"]=[[HIY去华山看仆人赴约论剑。]],["lifeText1"]=[[出身普通人家。]],["lifeText2"]=[[出身普通人家。]],["lifeText3"]=[[出身普通人家，对自己的下一代寄予厚望。]],["talkText"]=[[你说这人都这么一把年纪了，咋还会有这么重的玩心。;小时候陈芝麻烂谷子的事儿，谁还记得。]],["talktext1"]=[[希望我的孩子将来能成为大侠。;人往往会做自己小时候最不想做的事情，生活就是如此，即使你不愿，也还是得继续前进。;儿时的赌约，是我输了。]],["taskText"]=[[#mz：昔年我和他约定十年之后成为大侠，去华山论剑，如今十年已过，我虽然没能成为大侠，但还是不能毁约。我这便去华山一趟。]],["taskTitle"]=[[十年之约]]},["shenshi044"]={["acceptText"]=[[YEL#mz：若是此番能治好病就好了。]],["chatId"]=[[chat001;chat002;chat003;chat019]],["chatId1"]=[[chat001;chat002;chat003;chat019]],["eventId"]=[[shenshi044]],["eventTalk"]=[[我这老毛病也不知道还能不能治。]],["id"]=[[shenshi044]],["lifeEvent"]=[[#mz曾经也是一名闯荡江湖的侠客，后来一次打斗之中身受重伤，虽然及时医治，但还是落下病根。你和#mz闲聊之间，#mz讲了不少江湖上曾经发生的趣事给你听，逗得你哈哈大笑。]],["lifeEvent1"]=[[我最近感觉旧疾已经好多了。;虽然旧伤已经好了不少，但我现在觉得还是平静的日子比较好。;过去的事终将成为回忆。]],["lifeText"]=[[HIY去苏州城为仆人找徐天川治疗旧疾。]],["lifeText1"]=[[也曾是江湖儿女，不过那是以前的事了。]],["lifeText2"]=[[也曾是江湖儿女，不过那是以前的事了。]],["lifeText3"]=[[也曾是江湖儿女，不过那是以前的事了，因为受过伤，落下了病根。]],["talkText"]=[[您别看我这样，我曾经也是个闯荡江湖的人。;真怀念从前的日子。;这几天老毛病又犯了，晚上觉都睡不好。]],["talktext1"]=[[我最近感觉旧疾已经好多了。;虽然旧伤已经好了不少，但我现在觉得还是平静的日子比较好。;过去的事终将成为回忆。]],["taskText"]=[[#mz：近日来旧疾复发，夜晚疼痛难忍，日子一天比一天难熬。听说京城的名医徐天川近日来了苏州城中，我想告个假去求见徐大夫，看看能不能治好我的旧疾。]],["taskTitle"]=[[治疗旧疾]]},["shenshi045"]={["acceptText"]=[[YEL#mz：谢谢#ch#，我过几日无事便会回来。]],["chatId"]=[[chat001;chat002;chat003;chat019]],["chatId1"]=[[chat001;chat002;chat003;chat019]],["eventId"]=[[shenshi045]],["eventTalk"]=[[小桃到底出什么事了？让人有些担心。]],["id"]=[[shenshi045]],["lifeEvent"]=[[你和#mz闲聊之中，了解到#mz以前在将军府做事，本来顺风顺水，#mz却因为一件小事被扫地出门，流落街头之后，若不是你让#mz来此做事，#mz恐怕就要饿死街头。说到此处，#mz对你表示十分感激，也表示过去活得实在不值。]],["lifeEvent1"]=[[我已经和他们断绝关系，从今往后只跟着#ch#一人。;#ch#再造之恩，小的没齿难忘。]],["lifeText"]=[[HIY仆人去京城见小桃了，去看看究竟发生了什么。]],["lifeText1"]=[[出身普通人家，不过看起来也是见过世面的人。]],["lifeText2"]=[[出身普通人家，不过看起来也是见过世面的人。]],["lifeText3"]=[[曾在将军府呆过，做过高门大户的仆人。]],["talkText"]=[[我以前在将军府做过事，那会觉得自己就是个有头有脸的人物。;以前的我真蠢。;还是安安分分过日子吧。]],["talktext1"]=[[我已经和他们断绝关系，从今往后只跟着#ch#一人。]],["taskText"]=[[#mz：以前将军府的丫鬟小桃前几日来找到我，说是有要事相求。小桃以前待我不错，我想去京城几天，看看到底发生了什么。]],["taskTitle"]=[[千里相助]]},["shenshi046"]={["acceptText"]=[[YEL#mz：如此，我便先多谢#ch#了。那秋员外时常去金陵城中烟花之地作乐，我们便去看看。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi046]],["eventTalk"]=[[这次定要把他的宝贝都摸来。]],["id"]=[[shenshi046]],["lifeEvent"]=[[你见#mz平日里闲暇之时总会外出，颇为神秘，一日好奇心驱使之下，你隐匿行踪，跟随其外出，竟然发现#mz悄无声息地潜入一个大户人家，出来之时背上便多了个鼓鼓囊囊的布囊。你觉#mz平日为人不错，不知其为何会做出这种事，待#mz回来，你将其叫到跟前一番长谈，才知#mz竟然就是本地赫赫有名的侠盗，专行劫富济贫之事。你犹豫再三，最终没有声张。]],["lifeEvent1"]=[[那秋员外现在只怕是气得跺脚吧，哈哈。;先前盗取的财物我都已经分发给穷人了。;他怎么也不会想到是我偷的东西吧。]],["lifeText"]=[[HIY帮助仆人盗走宝物。]],["lifeText1"]=[[时常独自外出，颇为神秘。]],["lifeText2"]=[[身手十分矫健，很擅长隐匿气息。]],["lifeText3"]=[[是一名颇有名气的侠盗，专做劫富济贫之事。]],["talkText"]=[[义非义，侠非侠，盗非盗，邪非邪。;我和兵器打过不少交道，看#ch#的兵器有几件着实不错。;江湖之上有盗活人财者，有窃死人宝者，这些人或为己，或为他人，是非善恶，不得而谈。]],["talktext1"]=[[那秋员外现在只怕是气得跺脚吧，哈哈。;先前盗取的财物我都已经分发给穷人了。;他怎么也不会想到是我偷的东西吧。]],["taskText"]=[[#mz：#ch#没有报官，我不胜感激。有些富人表面是正人君子，背地却干着欺压百姓的勾当，而金陵城中的秋员外，便是这样一个伪君子。秋员外身怀重宝，我早就想去盗走，只是他带着侍卫，我一人无法靠近。虽然很唐突，但不知#ch#是否愿意助我一臂之力？]],["taskTitle"]=[[盗亦有道]]},["shenshi047"]={["acceptText"]=[[YEL#mz：有#ch#助阵，他们的死期到了。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi047]],["eventTalk"]=[[定要将重光赶尽杀绝。]],["id"]=[[shenshi047]],["lifeEvent"]=[[你与#mz聊起天来，谈及江湖中事，#mz对近来在江湖上为非作歹的重光教十分在意，惟愿杀之而后快。]],["lifeEvent1"]=[[若是#ch#再看到重光教的人，一定不要手下留情。;重光教的人坏得很，不要轻信他们。;上次#ch#出手便除掉了重光教的人，当真厉害。]],["lifeText"]=[[HIY和仆人一同去牛家村对抗重光。]],["lifeText1"]=[[身为江湖中人，心系武林。]],["lifeText2"]=[[不论身处何处，心中都颇向正道。]],["lifeText3"]=[[对外来教会重光为非作歹一事十分在意。]],["talkText"]=[[虽然说这江湖上有正有邪，但无论正邪，总归是江湖儿女的恩怨，绝轮不到外人插手。;我就是看不惯那些外来者。;若是我技不如人，自当服输，但若是旁人想就此骑到我辈头上，那绝不可能。]],["talktext1"]=[[若是#ch#再看到重光教的人，一定不要手下留情。;重光教的人坏得很，不要轻信他们。;上次#ch#出手便除掉了重光教的人，当真厉害。]],["taskText"]=[[#mz：我听说有一伙重光的人在牛家村一带为非作歹，这些人一日不除，我中原人士也无法清净。我现在就去除掉他们，#ch#要不要一同前往？]],["taskTitle"]=[[对抗重光]]},["shenshi048"]={["acceptText"]=[[YEL#mz：多一个人便多一分把握，多谢#ch#了。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi048]],["eventTalk"]=[[子山的仇，一定要报。]],["id"]=[[shenshi048]],["lifeEvent"]=[[你发现#mz平日里总是喜欢吹奏随身带着的玉笛，所奏十分动听，一时心中好奇，有心谈及此事，#mz告诉你自己原本有三位友人，均擅乐理，几人本共同隐居，后一人因无意中卷入纷争被杀，#mz重出江湖，便是为了寻仇。]],["lifeEvent1"]=[[红梅山庄本是正道，不知道为什么有他这种人在里面。;可惜子山就这么枉死。;那日子山酒醉得厉害，怎么可能还能听到他在说什么。]],["lifeText"]=[[HIY到少林替仆人了结恩怨。]],["lifeText1"]=[[总是随身带着玉笛，似有心事吹之不尽。]],["lifeText2"]=[[对音律十分在行，所奏之乐绕梁三日，不绝于耳。]],["lifeText3"]=[[有三位同擅音律的友人。]],["talkText"]=[[高山流水，曲高和寡。;我有三位友人，我们曾一同隐居，江湖上似乎称呼我们为竹林四杰。;人一旦被红尘俗世所扰，便再无法抽身。]],["talktext1"]=[[红梅山庄本是正道，不知道为什么有他这种人在里面。;可惜子山就这么枉死。;那日子山酒醉得厉害，怎么可能还能听到他在说什么。]],["taskText"]=[[#mz：我找寻多日，终于找到那仇人。那人现就藏身在少林，不知#ch#是否愿意随我一同前去。]],["taskTitle"]=[[竹林四杰]]},["shenshi049"]={["acceptText"]=[[YEL#mz：#ch#要是也去，我看夺得魁首是悬了。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi049]],["eventTalk"]=[[我已经按耐不住想去打擂了。]],["id"]=[[shenshi049]],["lifeEvent"]=[[你和#mz聊了会天，得知#mz对自己武功颇为自信，并有意想多与人交手以精进。#mz让你行走江湖之时也帮忙留意有没有什么地方有比武台，你答应了下来。]],["lifeEvent1"]=[[#ch#什么时候有空了再和我切磋吧。;以后去比武可得小心些。]],["lifeText"]=[[HIY同仆人一起去金陵城比武。]],["lifeText1"]=[[江湖中人，有几分实力。]],["lifeText2"]=[[对自己身手颇为自信。]],["lifeText3"]=[[喜欢四处比武并赢取钱财。]],["talkText"]=[[别人怎样看我不知道，我自己对自己身手还算是自信的。;一阵没有动筋骨，浑身难受。;有时候去比武场打擂挺好的，既能精进武艺，又能赚得钱财。]],["talktext1"]=[[#ch#什么时候有空了再和我切磋吧。;以后去比武可得小心些。]],["taskText"]=[[#mz：#ch#！我听说金陵城中有人设下擂台，邀人去比武，若是能赢，还能获得奖赏！咱们要不要去试试？]],["taskTitle"]=[[金陵比武]]},["shenshi050"]={["acceptText"]=[[YEL#mz：那太好了，多个人喝酒就是好啊。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi050]],["eventTalk"]=[[一同去尝尝苏帮菜的滋味吧。]],["id"]=[[shenshi050]],["lifeEvent"]=[[你和#mz聊起了美食，#mz显然十分感兴趣，并表示目前仍未吃过苏帮菜，有机会一定要去尝一尝。]],["lifeEvent1"]=[[苏帮菜与杭帮菜各有千秋，都是江南之味。;下次再与#ch#一同去喝酒。;那春在楼厨子手艺绝妙，春在楼开遍大江南北也是不无道理的。]],["lifeText"]=[[HIY到苏州春在楼找仆人喝酒。]],["lifeText1"]=[[在江湖上走南闯北，吃过不少地方美食。]],["lifeText2"]=[[在塞北待过，表示塞北并没有什么可以吃的。]],["lifeText3"]=[[目前仍旧在追求美食。]],["talkText"]=[[我在江湖上走南闯北，吃过不少地道美食。;以前在塞北待过一阵，那里土地贫瘠，啥吃的都没有，可馋死人了。;#ch#觉得面好吃还是饭好吃？]],["talktext1"]=[[苏帮菜与杭帮菜各有千秋，都是江南之味。;下次再与#ch#一同去喝酒。;那春在楼厨子手艺绝妙，春在楼开遍大江南北也是不无道理的。]],["taskText"]=[[#mz：我正打算去苏州吃一吃正宗的苏帮菜。#ch#要不要同去？]],["taskTitle"]=[[美食之旅]]},["shenshi051"]={["acceptText"]=[[YEL#mz：多谢#ch#成全！就此拜别！]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi051]],["eventTalk"]=[[世间恩怨又怎么说得清！]],["id"]=[[shenshi051]],["lifeEvent"]=[[#mz平日里不喜言谈，今天却出奇的找你闲聊，并且说出了自己的身世。#mz五六岁时与父母失散，被永夜楼收留后培养成了杀手，最后#mz逃出永夜楼。凭记忆回到家乡却满目疮痍，有人告诉#mz是金陵陈家动的手，为此#mz屠杀陈家。后来才知是被奸人利用，错杀好人。]],["lifeEvent1"]=[[我虽记挂过往恩怨，但远比以往来的怡然自得。;日行一善，或许真的能将罪孽洗清。;比起此前做杀手，如今要快活的多！]],["lifeText"]=[[HIY帮助门客去荆州城南了断恩怨。]],["lifeText1"]=[[不知从何而来，沉默寡言。]],["lifeText2"]=[[不知从何而来，沉默寡言，偶然提起故乡面色沉重。]],["lifeText3"]=[[不知从何而来，沉默寡言，偶然提起故乡面色沉重，手臂上有一条疤痕，是个过去有故事的人。]],["talkText"]=[[我过去的确做过错事，但圆方大师说善恶本就一念。;我就想好好侍奉恩主，世间纷扰不愿理会。;永远都是黑夜，哪里又会有光？]],["talktext1"]=[[多谢#ch#，此后必定以#ch#马首是瞻！;活在忏悔中又如何，知错方为善者！;只愿他放下仇恨，便是对在下的救赎！]],["taskText"]=[[#mz：#ch#，该还的迟早要还。当初我一念之仁放走陈家幺子，如今他约我荆州城南一会！]],["taskTitle"]=[[还报血仇]]},["shenshi052"]={["acceptText"]=[[YEL#mz：多谢#ch#成全！我虽有罪，但日后下了黄泉也有交代了！]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi052]],["eventTalk"]=[[若能查清当年之事，我便能解脱了！]],["id"]=[[shenshi052]],["lifeEvent"]=[[你见#mz虽有些胆小，但做事勤快又有正义感，便邀#mz月下饮酒闲聊。酒入愁肠，#mz说出了自己的身世。#mz本是山野之人，会些拳脚。一日救回了个受伤的男子，不料却是敌国细作，被人告发，落得全家抄斩。押运途中驿站突发大火，#mz侥幸逃走，苟且偷生。]],["lifeEvent1"]=[[但愿世间不再有冤屈。;若有机会还真想回故乡看看。;可以正大光明的立身于世竟是如此畅快！]],["lifeText"]=[[HIY前往襄阳城帮助门客洗清冤屈。]],["lifeText1"]=[[为人老实，虽有些懦弱但极具正义感。]],["lifeText2"]=[[为人老实，虽有些懦弱但极具正义感，身上有很多不知来历的鞭伤。]],["lifeText3"]=[[为人老实，虽有些懦弱但极具正义感，身上有很多不知来历的鞭伤，曾经得罪过官府的人。]],["talkText"]=[[什么狗屁黑白，都是假的！;这世道靠的还是拳脚！;一人吃饱，全家不饿，我倒宁愿饿上一饿！]],["talktext1"]=[[#ch#的大恩大德，我无以为报，可惜人死不能复生！;洗清冤屈原来是如此的畅快！;事情既然查明，爹娘泉下有知，定会欣慰！]],["taskText"]=[[#mz：当年村中赌鬼赵达将我告发，听闻他在襄阳现身，我想前去一问，我与他无冤无仇，为何如此对我！]],["taskTitle"]=[[襄阳洗冤]]},["shenshi053"]={["acceptText"]=[[YEL#mz：我就知道#ch#与他人不同，必会仗义相助。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi053]],["eventTalk"]=[[难不成明知此事，却要不理不问吗？]],["id"]=[[shenshi053]],["lifeEvent"]=[[前几天#mz路过扬州药铺，无意看到那学徒配药时竟然掺假，料他定是想私吞那些名贵药材，脾气暴躁的#mz决意要去阻止。]],["lifeEvent1"]=[[江湖我辈，既为医者，怎能放纵这种狡诈之徒横行。;打打杀杀我从不拦截，但若要玷污手上这根银针，那便不用废话！;哼，刀剑可取人性命，医药也可杀人于无形，多谢#ch#仗义相助。]],["lifeText"]=[[HIY前往扬州城协助#mz揭穿药铺学徒掺假。]],["lifeText1"]=[[书香世家，略懂医道。]],["lifeText2"]=[[书香世家，略懂医道，为此心存仁心。]],["lifeText3"]=[[书香世家，略懂医道。为此心存仁心，虽身在江湖不由自己，但有时眼中只有病者之分。]],["talkText"]=[[近日研读《金匮要略》我倒有些新的想法，或能研制出新的药方。;只需大黄、芒硝、桃仁、丹皮、冬瓜仁便能煎制出牡丹汤，#ch#是否需要？;医道不比江湖，但凡病者，不分善恶。]],["talktext1"]=[[还好及时揭发，否则不知有多少人要被这假药害去性命。;江湖打杀来的直白，不像这些无良小人，暗中作祟枉害人命。;我替那些百姓多谢#ch#了。]],["taskText"]=[[#mz：#ch#，那药铺学徒用树根掺假，私吞名贵药材，我必须赶去扬州药铺好好教训一番。]],["taskTitle"]=[[药为仁心]]},["shenshi054"]={["acceptText"]=[[YEL#mz：多谢#ch#。]],["chatId"]=[[chat003;chat004;chat008;chat010]],["chatId1"]=[[chat003;chat004;chat008;chat010]],["eventId"]=[[shenshi054]],["eventTalk"]=[[抽刀断水水更流，举杯消愁愁更愁。]],["id"]=[[shenshi054]],["lifeEvent"]=[[你和#mz闲聊起自己的些许见闻，不料#mz突然沉默不语，双眼失神的眺望远方，心事满怀而不愿对你诉说。直到夜半，忽听#mz喃喃自语。原来当年#mz一时失语，害的兄长被冤而死。故此多年，心生芥蒂，不喜言谈。]],["lifeEvent1"]=[[#ch#，如您有心事，也可与我述说，我必定竭尽所能的为您排忧解难。;自放下这多年心事，我便快活多了。]],["lifeText"]=[[HIY前往苏州白云山看望#mz。]],["lifeText1"]=[[有段故事的人，只要提起过往就沉默寡言。]],["lifeText2"]=[[有段故事的人，只要提起过往就沉默寡言，平日里说话谨慎。]],["lifeText3"]=[[有段故事的人，只要提起过往就沉默寡言，平日里说话谨慎，夜半之时，常能看见他在月下发呆。]],["talkText"]=[[#ch#若无事，我便去忙了。;#ch#说的极是。;#ch#多虑了，我并没有什么烦恼忧愁。]],["talktext1"]=[[有一个人能诉说原来是一件如此幸福之事，#ch#，谢谢你。;我牵挂这件事许久，兄长若要怪，我也只能来世偿还了。;#ch#替我解开了多年的心结，此后我必当报答。]],["taskText"]=[[#mz：#ch#，我想和你告几日假，想独自去苏州走走。]],["taskTitle"]=[[不语当年]]}},["career"]={["1"]={["Dailyup1"]=1.5,["Gossiplimit1"]=1,["Gossipvalue1"]=1,["Gossipzhongcheng1"]=0.75,["charactertype"]=[[guanjia001]],["leave1"]=2,["naoshi1"]=2,["rewardjiage1"]=6,["rewardtimes1"]=1,["rewardzhongcheng1"]=0.4},["10"]={["Dailyup1"]=1.5,["Gossiplimit1"]=1,["Gossipvalue1"]=0.75,["Gossipzhongcheng1"]=0.75,["charactertype"]=[[peilian001]],["leave1"]=1.2,["naoshi1"]=1.2,["rewardjiage1"]=3,["rewardtimes1"]=1,["rewardzhongcheng1"]=0.9},["2"]={["Dailyup1"]=1,["Gossiplimit1"]=1,["Gossipvalue1"]=0.8,["Gossipzhongcheng1"]=0.8,["charactertype"]=[[huyuan001]],["leave1"]=0.9,["naoshi1"]=0.9,["rewardjiage1"]=2,["rewardtimes1"]=1,["rewardzhongcheng1"]=0.6},["3"]={["Dailyup1"]=1.5,["Gossiplimit1"]=1.2,["Gossipvalue1"]=0.9,["Gossipzhongcheng1"]=1,["charactertype"]=[[shutong001]],["leave1"]=1.5,["naoshi1"]=1.4,["rewardjiage1"]=2,["rewardtimes1"]=1,["rewardzhongcheng1"]=1.2},["4"]={["Dailyup1"]=1,["Gossiplimit1"]=1,["Gossipvalue1"]=0.6,["Gossipzhongcheng1"]=0.6,["charactertype"]=[[xiunv001]],["leave1"]=1.4,["naoshi1"]=1.3,["rewardjiage1"]=3,["rewardtimes1"]=1,["rewardzhongcheng1"]=1.3},["5"]={["Dailyup1"]=1,["Gossiplimit1"]=1,["Gossipvalue1"]=0.6,["Gossipzhongcheng1"]=0.6,["charactertype"]=[[laonong001]],["leave1"]=1.3,["naoshi1"]=1.2,["rewardjiage1"]=3,["rewardtimes1"]=1,["rewardzhongcheng1"]=1.2},["6"]={["Dailyup1"]=1,["Gossiplimit1"]=1,["Gossipvalue1"]=0.8,["Gossipzhongcheng1"]=0.8,["charactertype"]=[[chuzi001]],["leave1"]=1,["naoshi1"]=0.9,["rewardjiage1"]=4,["rewardtimes1"]=1,["rewardzhongcheng1"]=1},["7"]={["Dailyup1"]=1,["Gossiplimit1"]=1,["Gossipvalue1"]=0.7,["Gossipzhongcheng1"]=0.7,["charactertype"]=[[tiejiang001]],["leave1"]=1.1,["naoshi1"]=1,["rewardjiage1"]=4,["rewardtimes1"]=1,["rewardzhongcheng1"]=1.2},["8"]={["Dailyup1"]=0.8,["Gossiplimit1"]=1,["Gossipvalue1"]=0.6,["Gossipzhongcheng1"]=0.6,["charactertype"]=[[puren001]],["leave1"]=0.9,["naoshi1"]=0.9,["rewardjiage1"]=2,["rewardtimes1"]=1,["rewardzhongcheng1"]=0.75},["9"]={["Dailyup1"]=2,["Gossiplimit1"]=1.5,["Gossipvalue1"]=1.2,["Gossipzhongcheng1"]=1.2,["charactertype"]=[[menke001]],["leave1"]=1.4,["naoshi1"]=1.3,["rewardjiage1"]=5,["rewardtimes1"]=1,["rewardzhongcheng1"]=1.3}},["character"]={["xingge001"]={["Dailyup"]=3,["Gossiplimit"]=16,["Gossipvalue"]=30,["Gossipzhongcheng"]=8,["character"]=[[沉默寡言]],["id"]=[[xingge001]],["leave"]=14,["leavetext"]=[[#mz呆立原地，讷讷地半响说不出话来。#mz双手抱拳，最后还是一言不发地离开了。]],["naoshi"]=9,["rewardjiage"]=30,["rewardtext"]=[[HIC你赏赐了些许东西给#mz，#mz很激动，嗫嗫嚅嚅地说不上话来。NOR]],["rewardtimes"]=1,["rewardzhongcheng"]=28},["xingge002"]={["Dailyup"]=2,["Gossiplimit"]=8,["Gossipvalue"]=20,["Gossipzhongcheng"]=4,["character"]=[[内向害羞]],["id"]=[[xingge002]],["leave"]=17,["leavetext"]=[[#mz脸色涨红，眼色中带着哀求和不忿，但就算如此，也没大声说话。#mz低头敛容，缓缓地走远了。]],["naoshi"]=11,["rewardjiage"]=40,["rewardtext"]=[[HIC你赏赐了些许东西给#mz，#mz顿时脸色涨红，用几不可闻的声音说了句“多谢#ch#”。NOR]],["rewardtimes"]=1,["rewardzhongcheng"]=50},["xingge003"]={["Dailyup"]=3,["Gossiplimit"]=24,["Gossipvalue"]=25,["Gossipzhongcheng"]=8,["character"]=[[细心谨慎]],["id"]=[[xingge003]],["leave"]=12,["leavetext"]=[[#mz一脸平静地向你辞行。虽然被遣散，#mz的脸上也看不到一丝怨怼或者忧愁，#mz仔细盘点和交接完毕手上的事情后，便离开了。]],["naoshi"]=9,["rewardjiage"]=25,["rewardtext"]=[[HIC你赏赐了些许东西给#mz，#mz眼中透着一股炙热和感激，但情绪克制得很好，只是轻声道谢。NOR]],["rewardtimes"]=1,["rewardzhongcheng"]=20},["xingge004"]={["Dailyup"]=5,["Gossiplimit"]=16,["Gossipvalue"]=45,["Gossipzhongcheng"]=8,["character"]=[[老实巴交]],["id"]=[[xingge004]],["leave"]=18,["leavetext"]=[[#mz脸上带着痛苦和不舍的神色向你辞行：“#ch#，请恕小的以后再不能服侍你了”。#mz转过身，慢慢地走远了……]],["naoshi"]=13,["rewardjiage"]=25,["rewardtext"]=[[HIC你赏赐了些许东西给#mz，#mz笑呵呵地接过，连连道谢。NOR]],["rewardtimes"]=1,["rewardzhongcheng"]=33},["xingge005"]={["Dailyup"]=